"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
  Database, 
  Download, 
  Plus, 
  RotateCcw, 
  Trash2, 
  AlertTriangle,
  FileJson,
  Calendar,
  HardDrive
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { 
  createBackupAction, 
  listBackupsAction, 
  restoreBackupAction, 
  deleteBackupAction 
} from "@/actions/database-actions";
import { unwrapActionResult } from "@/lib/result";
import { format } from "date-fns";
import { 
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface Backup {
  name: string;
  size: number;
  createdAt: Date;
}

export function DatabaseSettingsPanel() {
  const router = useRouter();
  const [backups, setBackups] = useState<Backup[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [selectedBackup, setSelectedBackup] = useState<string | null>(null);
  const [confirmRestore, setConfirmRestore] = useState(false);
  const [restoring, setRestoring] = useState(false);

  const fetchBackups = async () => {
    try {
      setLoading(true);
      const res = unwrapActionResult(await listBackupsAction(null));
      setBackups(res.backups);
    } catch (err) {
      toast.error("Failed to load backups");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBackups();
  }, []);

  const handleCreateBackup = async () => {
    try {
      setCreating(true);
      const res = unwrapActionResult(await createBackupAction(null));
      toast.success(`Backup created: ${res.fileName}`);
      fetchBackups();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to create backup");
    } finally {
      setCreating(false);
    }
  };

  const handleDeleteBackup = async (fileName: string) => {
    try {
      unwrapActionResult(await deleteBackupAction({ fileName }));
      toast.success("Backup deleted");
      fetchBackups();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to delete backup");
    }
  };

  const handleRestore = async () => {
    if (!selectedBackup) return;
    
    try {
      setRestoring(true);
      toast.info(`Restoring database from ${selectedBackup}...`);
      unwrapActionResult(await restoreBackupAction({ fileName: selectedBackup }));
      toast.success("Database restored successfully. Refreshing page...");
      router.refresh();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to restore database");
    } finally {
      setRestoring(false);
      setConfirmRestore(false);
      setSelectedBackup(null);
    }
  };

  const formatSize = (bytes: number) => {
    const kb = bytes / 1024;
    if (kb < 1024) return `${kb.toFixed(1)} KB`;
    return `${(kb / 1024).toFixed(1)} MB`;
  };

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        <Card className="border-slate-200 shadow-sm md:col-span-2">
          <CardHeader className="border-b border-slate-50">
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="font-serif text-xl font-bold text-slate-900">Available Backups</CardTitle>
                <CardDescription>View and manage your database snapshots.</CardDescription>
              </div>
              <Button 
                onClick={handleCreateBackup} 
                disabled={creating || loading}
                className="rounded-xl bg-slate-900 text-xs font-semibold"
              >
                {creating ? "Creating..." : (
                  <>
                    <Plus className="mr-2 h-4 w-4" />
                    New Backup
                  </>
                )}
              </Button>
            </div>
          </CardHeader>
          <CardContent className="p-0">
            {loading ? (
              <div className="flex h-40 items-center justify-center text-slate-400">Loading backups...</div>
            ) : backups.length === 0 ? (
              <div className="flex h-40 flex-col items-center justify-center space-y-2 text-slate-400">
                <Database className="h-8 w-8 opacity-20" />
                <p className="text-sm">No backups found.</p>
              </div>
            ) : (
              <div className="divide-y divide-slate-50">
                {backups.map((backup) => (
                  <div key={backup.name} className="flex items-center justify-between p-4 hover:bg-slate-50/50 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100 text-slate-600">
                        <FileJson className="h-5 w-5" />
                      </div>
                      <div className="space-y-1">
                        <p className="text-sm font-semibold text-slate-900">{backup.name}</p>
                        <div className="flex items-center gap-3 text-xs text-slate-400">
                          <span className="flex items-center gap-1">
                            <Calendar className="h-3 w-3" />
                            {format(new Date(backup.createdAt), "MMM d, yyyy HH:mm")}
                          </span>
                          <span className="flex items-center gap-1">
                            <HardDrive className="h-3 w-3" />
                            {formatSize(backup.size)}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-900"
                        onClick={() => {
                          setSelectedBackup(backup.name);
                          setConfirmRestore(true);
                        }}
                      >
                        <RotateCcw className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 rounded-lg text-rose-400 hover:bg-rose-50 hover:text-rose-600"
                        onClick={() => handleDeleteBackup(backup.name)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card className="border-slate-200 bg-slate-900 text-white shadow-lg shadow-slate-200">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 font-serif text-lg">
              <AlertTriangle className="h-5 w-5 text-amber-400" />
              Safety Notice
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-xs leading-relaxed text-slate-300">
              Database backups are stored locally on the server. They capture the entire state of your studio including projects, materials, and settings.
            </p>
            <div className="space-y-2 rounded-xl bg-white/5 p-4 text-[10px] text-slate-400 border border-white/10">
              <strong className="block font-bold uppercase tracking-widest text-white/50">Restoration Policy</strong>
              Restoring a backup will <span className="text-amber-400 font-bold underline">completely replace</span> the current database. All changes made since the selected backup will be lost.
            </div>
          </CardContent>
          <CardFooter>
             <p className="text-[10px] text-slate-500 italic">
               System Version: Pillar 2 SSOT Ready
             </p>
          </CardFooter>
        </Card>
      </div>

      <AlertDialog open={confirmRestore} onOpenChange={setConfirmRestore}>
        <AlertDialogContent className="rounded-2xl border-slate-200 bg-white shadow-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="font-serif text-xl font-bold text-slate-900">
              Restore Database?
            </AlertDialogTitle>
            <AlertDialogDescription className="text-slate-500">
              You are about to restore the database to the state captured in <span className="font-bold text-slate-900">{selectedBackup}</span>. 
              This is a destructive operation and cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="rounded-xl border-slate-200 text-xs font-semibold text-slate-600 hover:bg-slate-50">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction 
              onClick={(e) => {
                e.preventDefault();
                handleRestore();
              }}
              disabled={restoring}
              className="rounded-xl bg-slate-900 text-xs font-semibold text-white hover:bg-slate-800"
            >
              {restoring ? "Restoring..." : "Yes, Restore Database"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { 
  addActivity, 
  updateActivityContent,
  toggleActivityStatus, 
  deleteActivity,
  deferActivity
} from "@/actions/phase-actions";
import { Loader2, Plus, Trash2, CheckCircle2, Circle, MessageSquare, ArrowRightCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import { Role, PhaseName } from "@/generated/prisma";
import { usePhaseLive, Activity } from "@/ui_engine";
import { unwrapActionResult } from "@/lib/result";
import { ActivityListSorted } from "@/components/activity-list-sorted";

interface ActivityManagerProps {
  revisionId: string;
  isLocked: boolean;
  phaseStatus: string;
  phaseName: PhaseName;
  userId: string;
  userRole: Role;
  canMutate: boolean;
}

export function ActivityManager({
  revisionId,
  isLocked,
  phaseStatus,
  phaseName,
  canMutate,
}: ActivityManagerProps) {
  const { activities: contextActivities, syncNow } = usePhaseLive();
  const [internalActivities, setInternalActivities] = useState(contextActivities);
  const isDoneStatus = (status: string) => status === "DONE" || status === "COMPLETED";

  // Sync internal state with Provider whenever Provider data changes
  useEffect(() => {
    setInternalActivities(contextActivities);
  }, [contextActivities]);

  const [newContent, setNewContent] = useState("");
  const [loading, setLoading] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draftContent, setDraftContent] = useState("");

  const targetMode: "TODO" | "FEEDBACK" = phaseStatus.startsWith("ON_REVIEW") ? "FEEDBACK" : "TODO";
  const isEditable = !isLocked && canMutate;

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newContent.trim() || !isEditable) return;

    setLoading("adding");
    try {
      unwrapActionResult(await addActivity({ revisionId, content: newContent, mode: targetMode }));
      setNewContent("");
      // Trigger sync for immediate reflection
      void syncNow();
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(null);
    }
  };

  const handleToggle = async (id: string) => {
    if (!isEditable) return;
    setLoading(id);

    // Optimistic Toggle
    setInternalActivities(prev =>
      prev.map((a) =>
        a.id === id ? { ...a, status: isDoneStatus(a.status) ? "OPEN" : "COMPLETED" } : a
      )
    );

    try {
      unwrapActionResult(await toggleActivityStatus({ activityId: id }));
      void syncNow();
    } catch (error) {
      setInternalActivities(contextActivities);
      console.error(error);
    } finally {
      setLoading(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (!isEditable) return;
    if (!confirm("Are you sure you want to delete this?")) return;
    setLoading(id);

    // Optimistic Delete
    setInternalActivities(prev => prev.filter(a => a.id !== id));

    try {
      unwrapActionResult(await deleteActivity({ activityId: id }));
      void syncNow();
    } catch (error) {
      setInternalActivities(contextActivities);
      console.error(error);
    } finally {
      setLoading(null);
    }
  };

  const handleDefer = async (id: string) => {
    if (loading) return;
    if (!confirm("Move this task to project scope? It will no longer block this phase submission.")) return;
    setLoading(`defer-${id}`);

    try {
      unwrapActionResult(await deferActivity({ activityId: id }));
      void syncNow();
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(null);
    }
  };

  const beginEdit = (activity: Activity) => {
    setEditingId(activity.id);
    setDraftContent(activity.content);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setDraftContent("");
  };

  const handleSaveEdit = async (id: string) => {
    if (!isEditable || !draftContent.trim()) return;
    setLoading(`edit-${id}`);

    // Optimistic Update
    setInternalActivities(prev => prev.map(a => a.id === id ? { ...a, content: draftContent } : a));

    try {
      unwrapActionResult(await updateActivityContent({ activityId: id, content: draftContent }));
      cancelEdit();
      void syncNow();
    } catch (error) {
      setInternalActivities(contextActivities);
      console.error(error);
    } finally {
      setLoading(null);
    }
  };

  return (
    <div className="flex flex-col gap-4">

      {/* Add Form */}
      {isEditable && (
        <form onSubmit={handleAdd} className="flex gap-2">
          <Input
            value={newContent}
            onChange={(e) => setNewContent(e.target.value)}
            placeholder={`Add new ${targetMode.toLowerCase()} for ${phaseName.toLowerCase().replace(/_/g, " ")}...`}
            className="flex-1 bg-white border-zinc-200 focus-visible:ring-1 focus-visible:ring-slate-300 font-sans shadow-sm"
            disabled={loading === "adding"}
          />
          <Button 
            type="submit" 
            disabled={loading === "adding" || !newContent.trim()}
            className="bg-slate-900 hover:bg-slate-800 text-white font-sans font-medium px-5"
          >
            {loading === "adding" ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4 mr-1.5" />}
            Add
          </Button>
        </form>
      )}

      {/* Sorted Iteration Activities */}
      <ActivityListSorted
        activities={internalActivities}
        emptyMessage={`No discussed items for ${phaseName.toLowerCase().replace(/_/g, " ")} yet.`}
        renderItem={(activity) => (
          <div 
            key={activity.id}
            className={cn(
              "group flex items-center justify-between p-3 rounded-md border transition-all",
              isDoneStatus(activity.status)
                ? "bg-zinc-50 border-zinc-100 opacity-60" 
                : "bg-white border-zinc-200 shadow-sm hover:border-zinc-300"
            )}
          >
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => handleToggle(activity.id)}
                disabled={isLocked || loading === activity.id}
                className={cn(
                  "transition-colors",
                  !isEditable ? "cursor-default" : "cursor-pointer"
                )}
              >
                {activity.mode === "TODO" ? (
                  isDoneStatus(activity.status) ? (
                    <CheckCircle2 className="w-4 h-4 text-emerald-500" />
                  ) : (
                    <Circle className="w-4 h-4 text-slate-300 group-hover:text-slate-500" />
                  )
                ) : (
                  <MessageSquare className="w-4 h-4 mt-0.5 text-amber-500" />
                )}
              </button>
              {editingId === activity.id ? (
                <Input
                  value={draftContent}
                  onChange={(e) => setDraftContent(e.target.value)}
                  className="h-8 min-w-[280px] border-slate-200"
                  autoFocus
                  disabled={loading === `edit-${activity.id}`}
                />
              ) : (
                <span className={cn(
                  "text-sm font-sans",
                  isDoneStatus(activity.status) && "line-through text-slate-500"
                )}>
                  {activity.content}
                </span>
              )}
            </div>

            {isEditable && (
              <div className={cn(
                "flex items-center gap-1 transition-opacity",
                editingId === activity.id ? "opacity-100" : "opacity-0 group-hover:opacity-100"
              )}>
                {editingId === activity.id ? (
                  <>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => handleSaveEdit(activity.id)}
                      className="h-8 border-zinc-200 text-xs px-2"
                    >
                      {loading === `edit-${activity.id}` ? <Loader2 className="w-3 h-3 animate-spin" /> : "Save"}
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={cancelEdit}
                      className="h-8 text-xs text-slate-500 px-2"
                    >
                      Cancel
                    </Button>
                  </>
                ) : (
                  <>
                    {activity.mode === "TODO" && isEditable && (
                      <button
                        type="button"
                        onClick={() => handleDefer(activity.id)}
                        disabled={loading === `defer-${activity.id}`}
                        title="Defer to project level"
                        className="p-1 text-slate-300 hover:text-blue-600 transition-colors"
                      >
                        {loading === `defer-${activity.id}` ? <Loader2 className="w-4 h-4 animate-spin" /> : <ArrowRightCircle className="w-4 h-4" />}
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => handleDelete(activity.id)}
                      disabled={loading === activity.id}
                      className="p-1 text-slate-300 hover:text-red-600 transition-colors"
                    >
                      {loading === activity.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                    </button>
                  </>
                )}
              </div>
            )}
          </div>
        )}
      />

    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { AlertTriangle, Loader2, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { overrideRevision } from "@/actions/phase-actions";
import { unwrapActionResult } from "@/lib/result";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";

interface AdminRevisionOverrideProps {
  phaseId: string;
  currentVersion: {
    major: number;
    minor: number;
  };
}

type OverrideMode = "HARD_RESET_ACTIVE" | "HARD_RESET_PENDING";

export function AdminRevisionOverride({
  phaseId,
  currentVersion,
}: AdminRevisionOverrideProps) {
  const [isPending, startTransition] = useTransition();
  const [isOpen, setIsOpen] = useState(false);
  const [mode, setMode] = useState<OverrideMode>("HARD_RESET_ACTIVE");
  const [major, setMajor] = useState(String(currentVersion.major + 1));
  const [minor, setMinor] = useState("0");
  const [confirmed, setConfirmed] = useState(false);

  const parsedMajor = Number(major);
  const parsedMinor = Number(minor);

  const canSubmit =
    confirmed &&
    (mode === "HARD_RESET_PENDING" || 
      (Number.isInteger(parsedMajor) && parsedMajor >= 0 && Number.isInteger(parsedMinor) && parsedMinor >= 0));

  function handleOverride() {
    startTransition(async () => {
      try {
        unwrapActionResult(
          await overrideRevision({
            phaseId,
            targetMajorVersion: mode === "HARD_RESET_ACTIVE" ? parsedMajor : undefined,
            targetMinorVersion: mode === "HARD_RESET_ACTIVE" ? parsedMinor : undefined,
            mode,
            note: "Hard Reset by Admin",
          })
        );
        toast.success(
          mode === "HARD_RESET_ACTIVE" 
            ? `Phase reset to new revision v${parsedMajor}.${parsedMinor}`
            : "Phase reverted to Pending state."
        );
        setIsOpen(false);
        setConfirmed(false);
      } catch (error: unknown) {
        toast.error(error instanceof Error ? error.message : "Failed to override revision.");
      }
    });
  }

  return (
    <>
      <Button
        variant="outline"
        size="sm"
        disabled={isPending}
        onClick={() => setIsOpen(true)}
        className="h-8 border-amber-200 bg-amber-50/50 text-amber-700 hover:bg-amber-100 hover:text-amber-800"
      >
        {isPending ? (
          <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
        ) : (
          <ShieldCheck className="mr-1.5 h-3.5 w-3.5" />
        )}
        Admin Override
      </Button>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <div className="flex items-center gap-2 text-amber-600">
              <AlertTriangle className="h-5 w-5" />
              <DialogTitle>Admin Revision Override</DialogTitle>
            </div>
            <DialogDescription>
              Advanced administrative tools to manually adjust phase versions or reset state.
            </DialogDescription>
          </DialogHeader>

          <Tabs value={mode} onValueChange={(v) => setMode(v as OverrideMode)} className="w-full">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="HARD_RESET_ACTIVE" className="text-[10px] uppercase tracking-tighter">Reset to Revision</TabsTrigger>
              <TabsTrigger value="HARD_RESET_PENDING" className="text-[10px] uppercase tracking-tighter">Reset to Pending</TabsTrigger>
            </TabsList>

            <div className="mt-6 space-y-6">
              {/* Context Summary */}
              <div className="rounded-xl border border-slate-200 bg-slate-50 p-4 text-xs">
                <div className="text-slate-500 mb-1">Current Active State:</div>
                <div className="flex items-baseline gap-2">
                  <span className="font-serif text-lg font-black text-slate-900">v{currentVersion.major}.{currentVersion.minor}</span>
                  <span className="text-[10px] font-mono text-slate-400 uppercase tracking-widest bg-slate-200/50 px-1.5 py-0.5 rounded">Active</span>
                </div>
              </div>

              {/* Version Inputs - Only when ACTIVE */}
              {mode === "HARD_RESET_ACTIVE" && (
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="override-major" className="text-xs font-bold text-slate-600">Target Major</Label>
                    <Input
                      id="override-major"
                      type="number"
                      min="0"
                      className="h-12 text-lg font-serif"
                      value={major}
                      onChange={(e) => setMajor(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="override-minor" className="text-xs font-bold text-slate-600">Target Minor</Label>
                    <Input
                      id="override-minor"
                      type="number"
                      min="0"
                      className="h-12 text-lg font-serif"
                      value={minor}
                      onChange={(e) => setMinor(e.target.value)}
                    />
                  </div>
                </div>
              )}

              {/* Warning/Confirmation */}
              <div className="space-y-4">
                <div className="rounded-xl border border-amber-200 bg-red-50 p-4">
                  <div className="flex gap-3">
                    <Checkbox id="confirm-override" checked={confirmed} onCheckedChange={(c) => setConfirmed(!!c)} className="mt-0.5 border-amber-400 data-[state=checked]:bg-red-600 data-[state=checked]:border-red-600" />
                    <div className="space-y-1">
                      <Label htmlFor="confirm-override" className="text-sm font-semibold text-red-900 leading-tight">Confirm Destructive Reset</Label>
                      <p className="text-xs text-red-800/80 leading-relaxed">
                        This is a destructive action. Existing activities, files, and discussions for this phase will be permanently wiped out. {mode === "HARD_RESET_PENDING" && "The phase status will be reverted backwards to Pending."}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </Tabs>

          <DialogFooter className="mt-8 border-t pt-6">
            <Button variant="ghost" onClick={() => setIsOpen(false)} disabled={isPending}>
              Cancel
            </Button>
            <Button
              onClick={handleOverride}
              disabled={!canSubmit || isPending}
              className="min-w-[140px] transition-all bg-red-600 hover:bg-red-700"
            >
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Execute Reset
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Building, Folder, Calendar } from "lucide-react";
import { bootstrapProject } from "@/actions/project-actions";
import { CreatableSearch } from "@/components/ui/creatable-search";
import { format } from "date-fns";

interface UserOption {
  id: string;
  name: string;
  role: string;
}

interface CreateProjectDialogProps {
  designers: UserOption[];
  drafters: UserOption[];
  clients: Array<{ id: string; name: string }>;
  isAutoNamingEnabled: boolean;
}

export function CreateProjectDialog({
  designers,
  drafters,
  clients,
  isAutoNamingEnabled,
}: CreateProjectDialogProps) {
  const router = useRouter();
  const currentYear = new Date().getFullYear();
  const [open, setOpen] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [nameInput, setNameInput] = React.useState("");
  const [selectedClientId, setSelectedClientId] = React.useState<string>("");
  const [clientNameInput, setClientNameInput] = React.useState("");

  const trimmedName = nameInput.trim();
  const hasPrefixedName = /^\d{4}-\d{3}-/.test(trimmedName);
  const namingPreview = isAutoNamingEnabled
    ? trimmedName
      ? `${currentYear}-AUTO-${trimmedName}`
      : `${currentYear}-NNN-Project Name`
    : trimmedName || `${currentYear}-001-Project Name`;

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);
    setError(null);

    const formData = new FormData(event.currentTarget);
    const name = formData.get("name") as string;
    const client_name = clientNameInput;
    const pic_designer_id = formData.get("pic_designer_id") as string;
    const pic_drafter_id = formData.get("pic_drafter_id") as string;
    const opening_date = formData.get("opening_date") as string;

    if (!name || !pic_designer_id || !pic_drafter_id) {
        setError("Please fill in all required fields.");
        setLoading(false);
        return;
    }

    if (isAutoNamingEnabled && /^\d{4}-\d{3}-/.test(name.trim())) {
      setError("Enter only the readable project name. Year and sequence are generated automatically.");
      setLoading(false);
      return;
    }

    if (!isAutoNamingEnabled && !/^\d{4}-\d{3}-.+/.test(name.trim())) {
      setError("Project name must use the format: [YYYY]-[NNN]-[Name].");
      setLoading(false);
      return;
    }

    try {
      await bootstrapProject({
        name: name.trim(),
        pic_designer_id,
        pic_drafter_id,
        client_name: client_name || undefined,
        opening_date: opening_date ? new Date(opening_date) : undefined,
        core_project_type: "RETAIL", // default
      });
      setOpen(false);
      router.refresh(); // Refresh the page to see the new project
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Failed to create project.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button className="font-sans font-bold flex items-center gap-2 bg-slate-900 hover:bg-slate-800 text-white shadow-sm h-10 px-5 rounded-md tracking-wide">
          <Plus className="w-4 h-4" />
          Add Project
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px] font-sans">
        <DialogHeader>
          <DialogTitle className="font-serif text-xl font-bold">Create New Project</DialogTitle>
          <DialogDescription>
            Enter details to initialize a new project workflow.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="grid gap-4 py-4">
          {error && (
            <div className="p-2 border border-red-200 bg-red-50 text-red-600 rounded-md text-sm">
              {error}
            </div>
          )}
          <div className="grid gap-2">
            <Label htmlFor="name">Project Name <span className="text-red-500">*</span></Label>
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3">
              <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">Format</p>
              <p className="mt-1 font-mono text-xs text-slate-700">[YYYY]-[NNN]-[Name]</p>
              <p className="mt-2 text-xs text-slate-500">
                {isAutoNamingEnabled
                  ? "Auto-naming is enabled. Type only the readable project title."
                  : "Auto-naming is disabled. Enter the full project name manually."}
              </p>
              <p className="mt-2 text-xs text-slate-500">Preview: <span className="font-mono text-slate-700">{namingPreview}</span></p>
            </div>
            <div className="relative">
              <Folder className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
              <Input
                id="name"
                name="name"
                placeholder={
                  isAutoNamingEnabled
                    ? "e.g., Kopi Kenangan Mall"
                    : `${currentYear}-001-Kopi Kenangan Mall`
                }
                required
                className="pl-9"
                value={nameInput}
                onChange={(event) => setNameInput(event.target.value)}
              />
            </div>
            {isAutoNamingEnabled && hasPrefixedName ? (
              <p className="text-xs text-red-600">Use only the project title. The `YYYY-NNN-` prefix is added automatically.</p>
            ) : !isAutoNamingEnabled ? (
              <p className="text-xs text-slate-500">Format: [YYYY]-[NNN]-[Name]</p>
            ) : (
              <p className="text-xs text-slate-500">Type only the project title. Sequence number is assigned when the project is created.</p>
            )}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="client_name">Client Name</Label>
            <CreatableSearch
              options={clients}
              value={selectedClientId}
              onSelect={(id, name) => {
                setSelectedClientId(id);
                setClientNameInput(name);
              }}
              onCreate={(name) => {
                setSelectedClientId(""); // It's a new client
                setClientNameInput(name);
              }}
              placeholder="Search or type a new client..."
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="opening_date">Target Opening Date</Label>
            <Input id="opening_date" name="opening_date" type="date" className="border-slate-200" />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="pic_designer_id">PIC Designer <span className="text-red-500">*</span></Label>
            <select
              id="pic_designer_id"
              name="pic_designer_id"
              required
              className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <option value="">Select Designer</option>
              {designers.map((u) => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="pic_drafter_id">PIC Drafter <span className="text-red-500">*</span></Label>
            <select
              id="pic_drafter_id"
              name="pic_drafter_id"
              required
              className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <option value="">Select Drafter</option>
              {drafters.map((u) => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
          </div>
          <DialogFooter>
            <Button type="submit" disabled={loading} className="w-full bg-slate-900 text-white hover:bg-slate-800">
              {loading ? "Creating..." : "Initialize Project"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import Link from "next/link";
import { AlertTriangle, ExternalLink, FileText, Link as LinkIcon, UploadCloud } from "lucide-react";
import { Role } from "@/generated/prisma";
import { DeliverableUploadDialog } from "@/components/deliverable-upload-dialog";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { 
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { 
  TableCard, 
  TableCardHeader, 
  TableCardHead, 
  TableCardBody, 
  TableCardRow, 
  TableCardCell,
  Heading
} from "@/ui_engine";

export interface DeliverablePhaseRow {
  phaseId: string;
  phaseName: string;
  currentRevision: {
    id: string;
    version: string;
  } | null;
  latestFile: {
    id: string;
    file_name: string;
    file_url: string;
    link_url: string | null;
    is_external: boolean;
    created_at: Date;
    revision_version: string;
  } | null;
  isAuthorized: boolean;
}

interface DeliverablesTableProps {
  rows: DeliverablePhaseRow[];
  userId: string;
  userRole: Role;
}

function formatPhaseName(phaseName: string) {
  return phaseName.replace(/_/g, " ");
}

function formatRevisionLabel(version: string | null) {
  return version ? `Rev. ${version.slice(1)}` : "No revision";
}

function formatUploadedDate(date: Date | null) {
  if (!date) return "-";

  return new Intl.DateTimeFormat("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Asia/Jakarta",
  }).format(date);
}

export function DeliverablesTable({
  rows,
  userId,
  userRole,
}: DeliverablesTableProps) {
  const headerContent = (
    <div className="flex w-full items-start justify-between gap-6 py-2">
      <div>
        <Heading variant="uiMeta" level={4} className="opacity-40">Compliance Dashboard</Heading>
        <Heading level={2} className="mt-2">Phase Deliverable Compliance</Heading>
        <p className="mt-2 max-w-3xl text-sm text-slate-500">
          Exactly one row per phase. Each row compares the latest uploaded deliverable against the current revision baseline.
        </p>
      </div>

    </div>
  );

  return (
    <TableCard header={headerContent}>
      <TableCardHeader>
        <TableCardHead className="w-[14%]">Phase</TableCardHead>
        <TableCardHead className="w-[18%]">Current Revision</TableCardHead>
        <TableCardHead className="w-[30%]">File / Deliverable</TableCardHead>
        <TableCardHead className="w-[12%]">Type</TableCardHead>
        <TableCardHead className="w-[12%]">Uploaded Date</TableCardHead>
        <TableCardHead className="w-[14%] align-right">Action</TableCardHead>
      </TableCardHeader>
      <TableCardBody>
        {rows.length === 0 ? (
          <TableCardRow>
            <TableCardCell colSpan={6} className="py-20 text-center text-slate-400 italic">
              No phases found for this project.
            </TableCardCell>
          </TableCardRow>
        ) : (
          rows.map((row) => {
            const isOutdated =
              row.latestFile !== null &&
              row.currentRevision !== null &&
              row.latestFile.revision_version !== row.currentRevision.version;

            return (
              <TableCardRow 
                key={row.phaseId}
                className={cn(isOutdated && "bg-amber-50/40 hover:bg-amber-50/60")}
              >
                <TableCardCell>
                  <div className="flex flex-col">
                    <span className="font-sans text-sm font-bold uppercase tracking-[0.14em] text-slate-900">
                      {formatPhaseName(row.phaseName)}
                    </span>
                    <span className="mt-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-400">
                      Compliance Row
                    </span>
                  </div>
                </TableCardCell>
                <TableCardCell>
                  {(() => {
                    if (isOutdated && row.currentRevision) {
                      return (
                        <div className="flex items-center gap-1.5 flex-nowrap">
                          <Badge variant="outline" className="border-slate-200 bg-white font-mono text-[10px] text-slate-400 px-1.5 py-0">
                            {formatRevisionLabel(row.latestFile!.revision_version)}
                          </Badge>
                          <TooltipProvider>
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <AlertTriangle className="h-3.5 w-3.5 text-amber-500 animate-pulse cursor-help shrink-0" />
                              </TooltipTrigger>
                              <TooltipContent>
                                <p>Outdated</p>
                              </TooltipContent>
                            </Tooltip>
                          </TooltipProvider>
                          <span className="text-slate-300">→</span>
                          <Badge variant="outline" className="border-amber-200 bg-amber-50 font-mono text-[10px] font-bold text-amber-800 px-1.5 py-0">
                            {formatRevisionLabel(row.currentRevision.version)}
                          </Badge>
                        </div>
                      );
                    }

                    return (
                      <Badge variant="outline" className="border-slate-200 bg-white font-mono text-[11px] text-slate-700">
                        {formatRevisionLabel(row.currentRevision?.version ?? null)}
                      </Badge>
                    );
                  })()}
                </TableCardCell>
                <TableCardCell>
                  {!row.latestFile ? (
                    <div className="flex items-center gap-3 text-slate-400">
                      <div className="rounded-lg border border-dashed border-slate-200 bg-slate-50 p-2">
                        <FileText className="h-4 w-4" />
                      </div>
                      <span className="text-sm italic">No file uploaded</span>
                    </div>
                  ) : (
                    <div className="flex items-center gap-3 max-w-full overflow-hidden">
                      <div className="rounded-lg border border-slate-200 bg-slate-50 p-2 text-slate-500 shrink-0">
                        {row.latestFile.is_external ? <LinkIcon className="h-4 w-4" /> : <FileText className="h-4 w-4" />}
                      </div>
                      <div className="min-w-0 flex flex-col">
                        <p className="truncate text-sm font-semibold text-slate-900 leading-tight">
                          {row.latestFile.file_name}
                        </p>
                        {(row.latestFile.is_external ? row.latestFile.link_url : row.latestFile.file_url) && (
                          <Link
                            href={(row.latestFile.is_external ? row.latestFile.link_url : row.latestFile.file_url)!}
                            target="_blank"
                            className="mt-0.5 inline-flex items-center gap-1 text-[10px] font-medium text-slate-400 hover:text-slate-600 transition-colors"
                          >
                            <ExternalLink className="h-3 w-3" />
                            Open
                          </Link>
                        )}
                      </div>
                    </div>
                  )}
                </TableCardCell>
                <TableCardCell>
                  <Badge variant="outline" className="border-slate-200 bg-slate-50 text-[10px] font-bold uppercase tracking-[0.14em] text-slate-600">
                    {row.latestFile ? (row.latestFile.is_external ? "URL" : "File") : "-"}
                  </Badge>
                </TableCardCell>
                <TableCardCell>
                  <span className="text-xs text-slate-600">
                    {formatUploadedDate(row.latestFile?.created_at ?? null)}
                  </span>
                </TableCardCell>
                <TableCardCell align="right">
                  {(() => {
                    if (!row.isAuthorized) {
                      return <span className="text-xs font-medium text-slate-400">No access</span>;
                    }

                    if (!row.currentRevision) {
                      return <span className="text-xs font-medium text-slate-400">No revision</span>;
                    }

                    return (
                      <DeliverableUploadDialog
                        revisionId={row.currentRevision.id}
                        userId={userId}
                        userRole={userRole}
                        canMutate={row.isAuthorized}
                        phaseLabel={formatPhaseName(row.phaseName)}
                        revisionLabel={row.currentRevision.version}
                        triggerLabel={row.latestFile ? "Update" : "Upload"}
                        className={cn(
                          "h-8 px-4 text-[10px] font-black uppercase tracking-widest transition-all shadow-none",
                          isOutdated 
                            ? "border-amber-300 bg-amber-50/50 text-amber-700 hover:bg-amber-500 hover:text-white" 
                            : "border-slate-200 text-slate-500 hover:bg-slate-900 hover:text-white"
                        )}
                      />
                    );
                  })()}
                </TableCardCell>
              </TableCardRow>
            );
          })
        )}
      </TableCardBody>
    </TableCard>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { updateProjectMetadata } from "@/actions/project-actions";
import { CreatableSearch } from "@/components/ui/creatable-search";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Role, PhaseName } from "@/generated/prisma";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Edit2, User, MapPin, Calendar, Building2, Lock, CheckCircle2 } from "lucide-react";
import { Heading } from "@/ui_engine";
import { formatPhaseName, type ProgressState } from "@/lib/project-progress";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { ArrowRightCircle, Circle } from "lucide-react";

import { PhaseHeartbeatActivity } from "@/types/common";

interface UserOption {
  id: string;
  name: string;
  role: Role;
}

interface ClientOption {
  id: string;
  name: string;
}

interface ProjectOverviewFormProps {
  project: {
    id: string;
    name: string;
    client: {
      id: string;
      name: string;
    } | null;
    area: number | null;
    opening_date: Date | null;
    opening_date_display: string;
    opening_date_input_value: string;
    pic_designer_id: string;
    pic_drafter_id: string;
    designer_name: string;
    drafter_name: string;
  };
  designers: UserOption[];
  drafters: UserOption[];
  clients: ClientOption[];
  role: Role;
  canEdit: boolean;
  currentProgress?: ProgressState;
  phases?: {
    id: string;
    name_enum: PhaseName;
    order_index: number;
    status_enum: string;
  }[];
  deferredActivities?: PhaseHeartbeatActivity[];
}

export function ProjectOverviewForm({
  project,
  designers,
  drafters,
  clients,
  role,
  canEdit,
  currentProgress,
  phases,
  deferredActivities = [],
}: ProjectOverviewFormProps) {
  const router = useRouter();
  const [open, setOpen] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const isAdmin = role === "ADMIN";
  const canEditScopedFields = isAdmin || canEdit;
  const canEditProjectName = isAdmin;
  const canEditClient = isAdmin;
  const canEditArea = canEditScopedFields;
  const canEditOpening = canEditScopedFields;
  const canEditDic = isAdmin;
  const canEditDric = isAdmin;
  const [clientSearch, setClientSearch] = React.useState(project.client?.name ?? "");
  const [selectedClientId, setSelectedClientId] = React.useState<string>(
    project.client?.id ?? "none"
  );
  const [isClientDropdownOpen, setIsClientDropdownOpen] = React.useState(false);

  React.useEffect(() => {
    if (!open) {
      setClientSearch(project.client?.name ?? "");
      setSelectedClientId(project.client?.id ?? "none");
    }
  }, [open, project.client?.id, project.client?.name]);

  const filteredClients = React.useMemo(() => {
    const normalizedSearch = clientSearch.trim().toLowerCase();
    if (!normalizedSearch) {
      return clients;
    }

    return clients.filter((client) =>
      client.name.toLowerCase().includes(normalizedSearch)
    );
  }, [clientSearch, clients]);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!isAdmin && !canEdit) return;

    setLoading(true);
    setError(null);

    const formData = new FormData(event.currentTarget);
    const projectName = (formData.get("name") as string | null)?.trim() ?? "";
    const areaValue = (formData.get("area") as string).trim();
    const openingDateValue = formData.get("opening_date") as string;
    const picDesignerId = (formData.get("pic_designer_id") as string | null) ?? undefined;
    const picDrafterId = (formData.get("pic_drafter_id") as string | null) ?? undefined;
    const clientIdValue = (formData.get("client_id") as string | null) ?? "none";

    const parsedArea = areaValue === "" ? undefined : Number(areaValue);
    const clientNameInput = clientSearch;

    if (isAdmin && !projectName) {
      setError("Project name is required.");
      setLoading(false);
      return;
    }

    try {
      await updateProjectMetadata({
        projectId: project.id,
        name: projectName || undefined,
        clientId: selectedClientId === "none" ? null : selectedClientId || undefined,
        client_name: selectedClientId === "" ? clientSearch : undefined,
        area: parsedArea,
        opening_date: openingDateValue ? new Date(openingDateValue) : undefined,
        pic_designer_id: picDesignerId,
        pic_drafter_id: picDrafterId,
      });
      setOpen(false);
      router.refresh();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Failed to update project metadata.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-8 shadow-sm">
      <div className="flex items-start justify-between gap-6 border-b border-slate-200 pb-6 mb-8">
        <div>
          <Heading variant="uiMeta" level={6}>Project Metadata</Heading>
          <Heading level={2} className="mt-2 text-slate-900">Overview</Heading>
        </div>

        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild>
            <Button variant="outline" size="sm" className="h-9 rounded-lg border-slate-200 text-xs font-semibold shadow-none hover:bg-slate-50">
              <Edit2 className="mr-2 h-3.5 w-3.5" />
              Edit Information
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[500px]">
            <form onSubmit={handleSubmit}>
              <DialogHeader>
                <DialogTitle asChild>
                  <Heading level={3}>Edit Project Metadata</Heading>
                </DialogTitle>
                <DialogDescription>
                  Update project details and assigned PICs.
                </DialogDescription>
              </DialogHeader>

              <TooltipProvider delayDuration={0}>
                <div className="grid gap-6 py-6">
                  {error ? (
                    <div className="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-600">
                      {error}
                    </div>
                  ) : null}

                  <MetadataField
                    id="name"
                    label="Project Name"
                    disabled={!canEditProjectName}
                  >
                    <Input
                      id="name"
                      name="name"
                      defaultValue={project.name}
                      disabled={!canEditProjectName}
                      className="border-slate-200"
                    />
                  </MetadataField>

                  <MetadataField
                    id="client_id"
                    label="Client Name"
                    disabled={!canEditClient}
                  >
                    <CreatableSearch
                      options={[
                        { id: "none", name: "No Client" },
                        ...clients.map(c => ({ id: c.id, name: c.name }))
                      ]}
                      value={selectedClientId}
                      onSelect={(id: string, name: string) => {
                        setSelectedClientId(id);
                        setClientSearch(name);
                      }}
                      onCreate={(name: string) => {
                        setSelectedClientId(""); // Marker for "New Client"
                        setClientSearch(name);
                      }}
                      placeholder="Search or type a new client..."
                      disabled={!canEditClient}
                    />
                  </MetadataField>

                  <div className="grid grid-cols-2 gap-6">
                    <MetadataField id="area" label="Area (sqm)" disabled={!canEditArea}>
                      <div className="relative">
                        <Input
                          id="area"
                          name="area"
                          type="number"
                          defaultValue={project.area || ""}
                          disabled={!canEditArea}
                          className="border-slate-200 pr-12"
                        />
                        <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-medium text-slate-400">
                          sqm
                        </span>
                      </div>
                    </MetadataField>

                    <MetadataField id="opening_date" label="Target Opening" disabled={!canEditOpening}>
                      <div className="relative">
                        <Input
                          id="opening_date"
                          name="opening_date"
                          type="date"
                          defaultValue={project.opening_date_input_value}
                          disabled={!canEditOpening}
                          className="border-slate-200"
                        />
                      </div>
                    </MetadataField>
                  </div>

                  <div className="grid grid-cols-2 gap-6">
                    <MetadataField id="pic_designer_id" label="DIC (Designer)" disabled={!canEditDic}>
                      <select
                        id="pic_designer_id"
                        name="pic_designer_id"
                        defaultValue={project.pic_designer_id}
                        disabled={!canEditDic}
                        className="flex h-10 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-slate-900 disabled:bg-slate-50"
                      >
                        {designers.map((user) => (
                          <option key={user.id} value={user.id}>
                            {user.name}
                          </option>
                        ))}
                      </select>
                    </MetadataField>

                    <MetadataField id="pic_drafter_id" label="DRIC (Drafter)" disabled={!canEditDric}>
                      <select
                        id="pic_drafter_id"
                        name="pic_drafter_id"
                        defaultValue={project.pic_drafter_id}
                        disabled={!canEditDric}
                        className="flex h-10 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-slate-900 disabled:bg-slate-50"
                      >
                        {drafters.map((user) => (
                          <option key={user.id} value={user.id}>
                            {user.name}
                          </option>
                        ))}
                      </select>
                    </MetadataField>
                  </div>
                </div>
              </TooltipProvider>

              <DialogFooter className="gap-2 sm:gap-0">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setOpen(false)}
                  className="rounded-lg px-6"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={loading}
                  className="rounded-lg bg-slate-900 px-8 font-semibold text-white hover:bg-slate-800"
                >
                  {loading ? "Saving..." : "Save Changes"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {/* Progress Section - Placed prominently at the top */}
      {currentProgress && (
        <div className="mb-10 pb-8 border-b border-slate-100">
          <div className="flex flex-col gap-5">
            <div className="flex items-center gap-5">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-slate-900 text-white">
                <CheckCircle2 className="h-6 w-6" />
              </div>
              <div className="space-y-1.5">
                <p className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-400">Project Status & Progress</p>
                <div className="flex flex-wrap items-center gap-x-5 gap-y-3">
                  {currentProgress.type === 'PROJECT_DONE' ? (
                    <Heading level={1} className="text-emerald-600 font-bold uppercase tracking-tight text-3xl">PROJECT COMPLETED ✓</Heading>
                  ) : currentProgress.type === 'READY_FOR' ? (
                    <div className="flex items-center gap-3">
                      <Heading level={2} className="text-amber-600 uppercase tracking-tight">READY FOR {formatPhaseName(currentProgress.nextPhaseName)}</Heading>
                      <Badge variant="outline" className="bg-amber-50 border-amber-100 text-amber-700">Action Required</Badge>
                    </div>
                  ) : (
                    currentProgress.phases.map((p, idx) => (
                      <div key={idx} className="flex items-center gap-4">
                        <div className="flex items-baseline gap-2">
                          <Heading level={2} className="uppercase tracking-tight font-bold text-slate-900">
                            {formatPhaseName(p.name)}
                          </Heading>
                          <span className="text-base font-medium text-slate-400">
                            v{p.major}.{p.minor}
                          </span>
                        </div>
                        
                        {p.status_enum === 'ON_REVIEW_INTERNAL' && (
                          <Badge variant="outline" className="text-[10px] bg-indigo-50 border-indigo-100 text-indigo-700 px-3 py-1 font-bold tracking-wider uppercase rounded-md shadow-sm">
                            Internal Review
                          </Badge>
                        )}
                        {p.status_enum === 'ON_REVIEW_CLIENT' && (
                          <Badge variant="outline" className="text-[10px] bg-orange-50 border-orange-100 text-orange-700 px-3 py-1 font-bold tracking-wider uppercase rounded-md shadow-sm">
                            Client Review
                          </Badge>
                        )}
                        {p.status_enum === 'APPROVED_INTERNAL' && (
                          <Badge variant="outline" className="text-[10px] bg-emerald-50 border-emerald-100 text-emerald-700 px-3 py-1 font-bold tracking-wider uppercase rounded-md">
                            Approved
                          </Badge>
                        )}
                        {idx < currentProgress.phases.length - 1 && <span className="text-slate-200 text-3xl font-thin mx-1">/</span>}
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>

            {/* Progress Bar Visual */}
            <div className="space-y-2">
              <div className="flex justify-between items-end">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Phase Journey</span>
                {phases && currentProgress.type === 'IN_PROGRESS' && (
                  <span className="text-xs font-bold text-slate-900">
                    {Math.round(((phases.findIndex(p => p.name_enum === currentProgress.phases[currentProgress.phases.length - 1].name) + 1) / phases.length) * 100)}% Complete
                  </span>
                )}
              </div>
              {phases && (
                <div className="h-2 w-full overflow-hidden rounded-full bg-slate-50 border border-slate-100">
                  <div 
                    className={cn(
                      "h-full transition-all duration-1000 shadow-sm",
                      currentProgress.type === 'PROJECT_DONE' ? "bg-emerald-500" : "bg-slate-900"
                    )}
                    style={{ 
                      width: currentProgress.type === 'PROJECT_DONE' 
                        ? '100%' 
                        : currentProgress.type === 'IN_PROGRESS' && currentProgress.phases.length > 0
                          ? `${((phases.findIndex(p => p.name_enum === currentProgress.phases[currentProgress.phases.length - 1].name) + 1) / phases.length) * 100}%`
                          : '5%' 
                    }}
                  />
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Project Metadata Grid - Lower Priority */}
      <div className="grid grid-cols-2 gap-x-12 gap-y-10 md:grid-cols-4 pt-2">
        <div className="flex items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-slate-50 text-slate-400 border border-slate-100 shadow-sm">
            <Building2 className="h-5 w-5" />
          </div>
          <div className="space-y-1.5">
            <Heading variant="uiMeta" level={6} className="text-slate-400">Client Name</Heading>
            <p className="text-sm font-bold text-slate-900">
              {project.client?.name ?? "No Client Assigned"}
            </p>
          </div>
        </div>

        <div className="flex items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-slate-50 text-slate-400 border border-slate-100 shadow-sm">
            <MapPin className="h-5 w-5" />
          </div>
          <div className="space-y-1.5">
            <Heading variant="uiMeta" level={6} className="text-slate-400">Area (sqm)</Heading>
            <p className="text-sm font-bold text-slate-900">{project.area ? `${project.area} sqm` : "-"}</p>
          </div>
        </div>

        <div className="flex items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-slate-50 text-slate-400 border border-slate-100 shadow-sm">
            <Calendar className="h-5 w-5" />
          </div>
          <div className="space-y-1.5">
            <Heading variant="uiMeta" level={6} className="text-slate-400">Target Opening</Heading>
            <p className="text-sm font-bold text-slate-900">{project.opening_date_display}</p>
          </div>
        </div>

        <div className="flex items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-slate-50 text-slate-400 border border-slate-100 shadow-sm">
            <User className="h-5 w-5" />
          </div>
          <div className="space-y-1.5">
            <Heading variant="uiMeta" level={6} className="text-slate-400">Assigned Team</Heading>
            <div>
              <p className="text-sm font-bold text-slate-900">{project.designer_name} (DIC)</p>
              <p className="text-[11px] text-slate-500 font-medium">{project.drafter_name} (DRIC)</p>
            </div>
          </div>
        </div>
      </div>


      {/* Deferred Tasks Section */}
      {deferredActivities.length > 0 && (
        <div className="mt-12 rounded-xl border border-amber-100 bg-amber-50/30 p-6">
          <div className="flex items-center gap-3 mb-4">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-amber-100 text-amber-600">
              <ArrowRightCircle className="h-4 w-4" />
            </div>
            <div>
              <Heading level={6} className="text-amber-900 font-bold uppercase tracking-wider text-[11px]">Deferred Project Tasks</Heading>
              <p className="text-xs text-amber-600 font-medium">Items moved from phases to maintain momentum</p>
            </div>
          </div>

          <div className="space-y-2">
            {deferredActivities.map((activity) => {
              const originPhase = phases?.find(p => p.id === activity.phase_id);
              return (
                <div 
                  key={activity.id}
                  className="flex items-center justify-between p-3 rounded-lg bg-white border border-amber-100 shadow-sm"
                >
                  <div className="flex items-center gap-3">
                    {activity.status === "DONE" || activity.status === "COMPLETED" ? (
                      <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                    ) : (
                      <Circle className="w-4 h-4 text-amber-300 shrink-0" />
                    )}
                    <span className={cn(
                      "text-sm font-sans text-slate-700",
                      (activity.status === "DONE" || activity.status === "COMPLETED") && "line-through opacity-50"
                    )}>
                      {activity.content}
                    </span>
                  </div>
                  
                  {originPhase && (
                    <Badge variant="outline" className="text-[10px] bg-amber-100/50 border-amber-200 text-amber-800 font-bold px-2 py-0.5 whitespace-nowrap">
                      Deferred from {formatPhaseName(originPhase.name_enum)} ({activity.deferred_from_version})
                    </Badge>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function MetadataField({
  id,
  label,
  disabled,
  children,
}: {
  id: string;
  label: string;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  const content = (
    <div className="grid gap-2.5">
      <Label htmlFor={id} className="flex items-center gap-2 text-[13px] font-bold text-slate-700">
        <span>{label}</span>
        {disabled ? <Lock className="h-3.5 w-3.5 text-slate-300" /> : null}
      </Label>
      {children}
    </div>
  );

  if (!disabled) {
    return content;
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div className="cursor-not-allowed opacity-80">{content}</div>
      </TooltipTrigger>
      <TooltipContent side="top" className="bg-slate-900 text-white border-none shadow-xl">
        <p className="text-xs font-semibold">Restricted Access</p>
      </TooltipContent>
    </Tooltip>
  );
}

"use client";

import { useState } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { TodayTaskItem } from "@/components/today-task-item";
import { TodayInlineAdd } from "@/components/today-inline-add";
import { cn } from "@/lib/utils";

interface Task {
  id: string;
  content: string;
  status: string;
  mode: string;
  projectName: string;
  phaseName: string;
  isUrgent: boolean;
}

interface Phase {
  id: string;
  name: string;
  status: string;
  revisionId?: string;
  tasks: Task[];
}

interface Project {
  id: string;
  name: string;
  isUrgent: boolean;
  phases: Phase[];
}

interface TodayViewProps {
  projects: Project[];
}

type RenderItem = 
  | { type: "projectHeader"; id: string; projectId: string; name: string; isUrgent: boolean }
  | { type: "phaseHeader"; id: string; projectId: string; phaseName: string }
  | { type: "task"; id: string; projectId: string; activity: Task }
  | { 
      type: "inlineAdd"; 
      id: string; 
      projectId: string; 
      phase: { id: string; name: string; revisionId: string; status: string };
      mode: "TODO" | "FEEDBACK" 
    };

export function TodayView({ projects }: TodayViewProps) {
  const [activeTab, setActiveTab] = useState("open");
  const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(new Set());

  const toggleProject = (projectId: string) => {
    setCollapsedProjects((prev) => {
      const next = new Set(prev);
      if (next.has(projectId)) {
        next.delete(projectId);
      } else {
        next.add(projectId);
      }
      return next;
    });
  };

  const buildFlatList = (isDone: boolean) => {
    const list: RenderItem[] = [];

    projects.forEach((project) => {
      const projectPhases = project.phases.map(phase => ({
        ...phase,
        tasks: phase.tasks.filter(t => (t.status === "DONE" || t.status === "COMPLETED") === isDone)
      })).filter(phase => phase.tasks.length > 0);

      if (projectPhases.length === 0) return;

      // Project Header
      list.push({
        type: "projectHeader",
        id: `project-${project.id}`,
        projectId: project.id,
        name: project.name,
        isUrgent: project.isUrgent
      });

      if (!collapsedProjects.has(project.id)) {
        // Subtle Phase Headers and Tasks
        projectPhases.forEach((phase) => {
          // Phase Header
          list.push({
            type: "phaseHeader",
            id: `phase-${phase.id}`,
            projectId: project.id,
            phaseName: phase.name
          });

          // Tasks
          phase.tasks.forEach((task) => {
            list.push({
              type: "task",
              id: `task-${task.id}`,
              projectId: project.id,
              activity: task
            });
          });

          // Inline Add specifically for THIS phase
          if (!isDone && phase.revisionId) {
            list.push({
              type: "inlineAdd",
              id: `add-phase-${phase.id}`,
              projectId: project.id,
              phase: {
                  id: phase.id,
                  name: phase.name,
                  revisionId: phase.revisionId,
                  status: phase.status
              },
              mode: phase.status.startsWith("ON_REVIEW") ? "FEEDBACK" : "TODO"
            });
          }
        });
      }
    });

    return list;
  };

  const openList = buildFlatList(false);
  const doneList = buildFlatList(true);

  const renderFlatList = (items: RenderItem[]) => {
    return (
      <div className="flex flex-col animate-in fade-in duration-300">
        {items.map((item) => {
          switch (item.type) {
            case "projectHeader":
              const isCollapsed = collapsedProjects.has(item.projectId);
              return (
                <div 
                  key={item.id} 
                  className="mt-12 flex cursor-pointer items-center justify-between border-b border-slate-200 pb-2 first:mt-4 group/header select-none"
                  onClick={() => toggleProject(item.projectId)}
                >
                  <div className="flex items-center gap-3">
                    <svg
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="3"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className={cn(
                        "h-2.5 w-2.5 transition-transform duration-200 text-slate-300 group-hover/header:text-slate-600",
                        !isCollapsed && "rotate-90"
                      )}
                    >
                      <path d="M9 18l6-6-6-6" />
                    </svg>
                    <h3 className="flex items-center gap-2 font-sans text-[11px] font-bold uppercase tracking-[0.22em] text-slate-900 transition-colors">
                      {item.name}
                      {item.isUrgent && (
                        <span className="flex items-center gap-1.5 ml-2">
                          <span className="text-red-600">●</span>
                          <span className="text-red-600">URGENT</span>
                        </span>
                      )}
                    </h3>
                  </div>
                </div>
              );
            case "phaseHeader":
              return (
                <div key={item.id} className="mt-8 mb-2 pl-8 flex items-center gap-2 first:mt-2 animate-in fade-in duration-500">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                    {item.phaseName}
                  </span>
                  <div className="h-[1px] flex-1 bg-slate-50" />
                </div>
              );
            case "task":
              return (
                <div key={item.id} className="pl-8">
                  <TodayTaskItem
                    id={item.activity.id}
                    label={item.activity.content}
                    isChecked={item.activity.status === "DONE" || item.activity.status === "COMPLETED"}
                    mode={item.activity.mode}
                    isUrgent={item.activity.isUrgent}
                  />
                </div>
              );
            case "inlineAdd":
              return (
                <div key={item.id} className="pl-8 py-2">
                  <TodayInlineAdd
                    phases={[item.phase]}
                    mode={item.mode}
                    buttonLabel={`+ Add ${item.mode === "FEEDBACK" ? "feedback" : "todo"} to ${item.phase.name}...`}
                    placeholder={`+ Add ${item.mode === "FEEDBACK" ? "feedback" : "todo"} to ${item.phase.name}...`}
                    className="opacity-50 hover:opacity-100 transition-opacity"
                  />
                </div>
              );
            default:
              return null;
          }
        })}
      </div>
    );
  };

  return (
    <Tabs defaultValue="open" className="w-full" onValueChange={setActiveTab}>
      <TabsList className="mb-6 flex h-auto w-full justify-start gap-6 rounded-none border-b border-slate-100 bg-transparent p-0">
        <TabsTrigger 
          value="open" 
          className="rounded-none border-b-2 border-transparent px-1 pb-3 pt-2 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 shadow-none transition-all data-[state=active]:border-slate-900 data-[state=active]:bg-transparent data-[state=active]:text-slate-900"
        >
          Open Tasks ({projects.reduce((acc, p) => acc + p.phases.reduce((acc2, ph) => acc2 + ph.tasks.filter(t => t.status !== "DONE" && t.status !== "COMPLETED").length, 0), 0)})
        </TabsTrigger>
        <TabsTrigger 
          value="done" 
          className="rounded-none border-b-2 border-transparent px-1 pb-3 pt-2 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 shadow-none transition-all data-[state=active]:border-slate-900 data-[state=active]:bg-transparent data-[state=active]:text-slate-900"
        >
          Completed
        </TabsTrigger>
      </TabsList>

      <TabsContent value="open" className="mt-0 focus-visible:ring-0">
        {openList.length > 0 ? (
          renderFlatList(openList)
        ) : (
          <p className="py-20 text-center font-sans text-xs text-slate-300 italic">No open tasks.</p>
        )}
      </TabsContent>

      <TabsContent value="done" className="mt-0 focus-visible:ring-0">
        {doneList.length > 0 ? (
          renderFlatList(doneList)
        ) : (
          <p className="py-20 text-center font-sans text-xs text-slate-300 italic">No completed tasks.</p>
        )}
      </TabsContent>
    </Tabs>
  );
}

