import * as React from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Maximize2, X, Download } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface ImageLightboxProps {
  src?: string | null;
  alt?: string;
  trigger?: React.ReactNode;
  className?: string;
  onClose?: () => void;
}

export function ImageLightbox({ src, alt = "Image", trigger, className, onClose }: ImageLightboxProps) {
  const [internalIsOpen, setInternalIsOpen] = React.useState(false);

  const isControlled = onClose !== undefined;
  const isOpen = isControlled ? !!src : internalIsOpen;

  const handleOpenChange = (open: boolean) => {
    if (!open && onClose) {
      onClose();
    }
    if (!isControlled) {
      setInternalIsOpen(open);
    }
  };

  const handleDownload = async () => {
    if (!src) return;
    try {
      const response = await fetch(src);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = alt || "download";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error("Failed to download image", error);
    }
  };

  if (!src && isControlled) return null;

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        {trigger || (
          <div className={cn("relative cursor-zoom-in group", className)}>
            <img src={src!} alt={alt} className="w-full h-full object-cover rounded-md" />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
              <Maximize2 className="w-5 h-5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>
          </div>
        )}
      </DialogTrigger>
      <DialogContent showCloseButton={false} className="max-w-[95vw] max-h-[95vh] p-0 border-none bg-black/95 overflow-hidden flex flex-col items-center justify-center">
        <DialogHeader className="sr-only">
          <DialogTitle>{alt}</DialogTitle>
          <DialogDescription>Full size image preview</DialogDescription>
        </DialogHeader>

        <div className="relative w-full h-full flex items-center justify-center p-4">
          <img
            src={src!}
            alt={alt}
            className="max-w-full max-h-[90vh] object-contain shadow-2xl animate-in zoom-in-95 duration-300"
          />
        </div>

        <div className="absolute top-4 right-4 flex items-center gap-2 z-50">
          <button
            onClick={handleDownload}
            className="p-2 rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors backdrop-blur-md flex items-center justify-center"
          >
            <Download className="w-5 h-5" />
            <span className="sr-only">Download</span>
          </button>

          <button
            onClick={() => handleOpenChange(false)}
            className="p-2 rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors backdrop-blur-md flex items-center justify-center"
          >
            <X className="w-6 h-6" />
            <span className="sr-only">Close</span>
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { X, Plus } from "lucide-react";
import { Badge } from "./badge";
import { Input } from "./input";
import { cn } from "@/lib/utils";

interface TagInputProps {
  placeholder?: string;
  tags: string[];
  onChange: (tags: string[]) => void;
  className?: string;
}

export function TagInput({
  placeholder = "Add tag...",
  tags = [],
  onChange,
  className
}: TagInputProps) {
  const [inputValue, setInputValue] = React.useState("");

  const addTag = (tag: string) => {
    const trimmed = tag.trim();
    if (!trimmed) return;

    // Split by comma in case someone pastes a list or types fast
    const newTags = trimmed.split(/[,]+/)
      .map(t => t.trim())
      .filter(t => t && !tags.includes(t));

    if (newTags.length > 0) {
      onChange([...tags, ...newTags]);
      setInputValue("");
    } else {
      setInputValue("");
    }
  };

  const removeTag = (tagToRemove: string) => {
    onChange(tags.filter(t => t !== tagToRemove));
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" || e.key === ",") {
      e.preventDefault();
      addTag(inputValue);
    } else if (e.key === "Backspace" && !inputValue && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <div className="flex flex-wrap gap-2 min-h-10 p-2 rounded-xl bg-slate-50 border border-transparent focus-within:border-slate-200 transition-all">
        {tags.map((tag) => (
          <Badge
            key={tag}
            variant="secondary"
            className="pl-2 pr-1 py-1 h-7 border-none bg-white shadow-sm text-slate-700 font-inter text-[11px] font-bold group flex items-center gap-1 animate-in zoom-in-95 duration-200"
          >
            {tag}
            <button
              type="button"
              onClick={() => removeTag(tag)}
              className="h-5 w-5 rounded-md hover:bg-slate-100 flex items-center justify-center transition-colors text-slate-400 hover:text-slate-900"
            >
              <X className="h-3 w-3" />
            </button>
          </Badge>
        ))}
        <input
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={() => addTag(inputValue)}
          placeholder={tags.length === 0 ? placeholder : ""}
          className="flex-1 bg-transparent border-none focus:ring-0 text-sm font-inter min-w-[120px] h-7"
        />
      </div>
      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest px-1 flex items-center gap-1.5">
         <Plus className="h-3 w-3" /> Press Enter or Comma to add tags
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { Upload, Loader2, Crop, X, Check, Image as ImageIcon } from "lucide-react";
import Cropper, { type Area, type Point } from "react-easy-crop";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { toast } from "sonner";
import { compressImage, getCroppedImg } from "@/lib/utils/image-utils";
import { uploadLibraryImage } from "@/extensions/library/lib/upload-client";
import { cn } from "@/lib/utils";

interface UniversalImageUploaderProps {
  initialImageUrl?: string | null;
  onUploadComplete: (urls: { original: string; cover: string }) => void;
  aspectRatio?: number;
  className?: string;
  label?: string;
}

export function UniversalImageUploader({
  initialImageUrl,
  onUploadComplete,
  aspectRatio = 1,
  className,
  label = "Upload Image",
}: UniversalImageUploaderProps) {
  const [imageFile, setImageFile] = React.useState<File | null>(null);
  const [imageSrc, setImageSrc] = React.useState<string | null>(null);
  const [crop, setCrop] = React.useState<Point>({ x: 0, y: 0 });
  const [zoom, setZoom] = React.useState(1);
  const [croppedAreaPixels, setCroppedAreaPixels] = React.useState<Area | null>(null);
  const [showCropper, setShowCropper] = React.useState(false);
  const [uploadStatus, setUploadStatus] = React.useState<"IDLE" | "COMPRESSING" | "UPLOADING" | "SUCCESS">("IDLE");
  const [previewUrl, setPreviewUrl] = React.useState<string | null>(initialImageUrl || null);

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setImageFile(file);
      const reader = new FileReader();
      reader.onload = () => {
        setImageSrc(reader.result as string);
        setShowCropper(true);
      };
      reader.readAsDataURL(file);
    }
  };

  const onCropComplete = (_: Area, pixelCrop: Area) => {
    setCroppedAreaPixels(pixelCrop);
  };

  const handleFinalize = async () => {
    if (!imageFile || !imageSrc || !croppedAreaPixels) return;

    setUploadStatus("COMPRESSING");
    try {
      const timestamp = Date.now();
      const fileName = `${timestamp}-${imageFile.name.replace(/\s/g, "_")}`;

      // 1. Compress Original
      const compressedOriginal = await compressImage(imageFile);

      // 2. Crop Cover
      const croppedCoverBlob = await getCroppedImg(imageSrc, croppedAreaPixels);
      if (!croppedCoverBlob) throw new Error("Failed to crop image");

      // 3. Upload Both
      setUploadStatus("UPLOADING");
      const originalPath = `originals/${fileName}`;
      const coverPath = `covers/${fileName}`;

      const [originalUrl, coverUrl] = await Promise.all([
        uploadLibraryImage(compressedOriginal, originalPath),
        uploadLibraryImage(croppedCoverBlob, coverPath)
      ]);

      onUploadComplete({ original: originalUrl, cover: coverUrl });
      setPreviewUrl(coverUrl);
      setUploadStatus("IDLE");
      setShowCropper(false);
      toast.success("Image uploaded successfully");
    } catch (error) {
      setUploadStatus("IDLE");
      const message = error instanceof Error ? error.message : "Upload failed";
      toast.error(message);
    }
  };

  return (
    <div className={cn("space-y-4", className)}>
      <div 
        className="relative aspect-square rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center gap-3 overflow-hidden group cursor-pointer hover:bg-slate-100/50 transition-all"
        onClick={() => !showCropper && document.getElementById("universal-image-input")?.click()}
      >
        {previewUrl ? (
          <img src={previewUrl} className="w-full h-full object-cover" alt="Preview" />
        ) : (
          <>
            <div className="h-12 w-12 rounded-xl bg-white shadow-sm flex items-center justify-center text-slate-400 group-hover:text-slate-900 transition-colors">
              <Upload className="h-6 w-6" />
            </div>
            <div className="text-center">
              <span className="text-[10px] text-slate-900 font-bold uppercase tracking-widest block">{label}</span>
              <span className="text-[9px] text-slate-400 font-medium">JPG, PNG up to 5MB</span>
            </div>
          </>
        )}

        <input
          id="universal-image-input"
          type="file"
          accept="image/*"
          onChange={onFileChange}
          className="hidden"
        />

        {uploadStatus !== "IDLE" && (
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm flex flex-col items-center justify-center gap-3 z-20">
            <Loader2 className="h-8 w-8 animate-spin text-white" />
            <span className="text-[10px] font-black text-white uppercase tracking-[0.2em] animate-pulse">
              {uploadStatus === "COMPRESSING" ? "Processing..." : "Uploading..."}
            </span>
          </div>
        )}

        {previewUrl && !showCropper && uploadStatus === "IDLE" && (
           <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <Button 
                variant="destructive" 
                size="icon" 
                className="h-8 w-8 rounded-full shadow-lg"
                onClick={(e) => {
                  e.stopPropagation();
                  setPreviewUrl(null);
                  onUploadComplete({ original: "", cover: "" });
                }}
              >
                <X className="h-4 w-4" />
              </Button>
           </div>
        )}
      </div>

      <Dialog open={showCropper} onOpenChange={setShowCropper}>
        <DialogContent className="sm:max-w-[500px] p-0 overflow-hidden border-none shadow-2xl rounded-[2rem]">
          <DialogHeader className="p-6 bg-slate-900 text-white">
            <DialogTitle className="font-lora text-xl font-medium flex items-center gap-2">
              <Crop className="h-5 w-5" /> Adjust Image Crop
            </DialogTitle>
          </DialogHeader>

          <div className="relative h-[400px] bg-slate-100">
            {imageSrc && (
              <Cropper
                image={imageSrc}
                crop={crop}
                zoom={zoom}
                aspect={aspectRatio}
                onCropChange={setCrop}
                onCropComplete={onCropComplete}
                onZoomChange={setZoom}
              />
            )}
          </div>

          <DialogFooter className="p-6 bg-white border-t border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4 flex-1">
               <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Zoom</span>
               <input
                 type="range"
                 value={zoom}
                 min={1}
                 max={3}
                 step={0.1}
                 onChange={(e) => setZoom(Number(e.target.value))}
                 className="flex-1 accent-slate-900"
               />
            </div>
            <div className="flex items-center gap-2">
              <Button variant="ghost" onClick={() => setShowCropper(false)} className="rounded-xl px-6 font-bold text-[10px] uppercase tracking-widest text-slate-400">
                Cancel
              </Button>
              <Button onClick={handleFinalize} className="bg-slate-900 hover:bg-slate-800 text-white rounded-xl px-8 shadow-xl shadow-slate-200 transition-all font-bold text-[10px] uppercase tracking-widest">
                Save & Upload
              </Button>
            </div>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import * as React from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Users, Package, Search, Filter, Warehouse, Plus, LayoutGrid, ArrowRightCircle } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { VendorTable } from "./VendorTable";
import { PhysicalInventoryTable } from "./PhysicalInventoryTable";
import { LibraryFormModal } from "./LibraryFormModal";
import { MaterialCatalogWithRelations, LibraryVendor, ProjectMaterialRequestWithDetails } from "../types";
import { MaterialTable } from "./MaterialTable";
import { MaterialRequestTable } from "./MaterialRequestTable";
import { Button } from "@/components/ui/button";
import { deleteMaterialAction, updateMaterialAction } from "../actions/library-actions";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Heading, ActionSidebar, ActionSidebarSection, ActionSidebarItem, TableCard } from "@/ui_engine";
import { ErrorBoundary } from "@/components/shared/error-boundary";
import { ErrorFallback } from "@/components/shared/error-fallback";

interface LibraryTabsProps {
  vendors: LibraryVendor[];
  materials: MaterialCatalogWithRelations[];
  categories: string[];
  materialCategories?: string[];
  fixtureCategories?: string[];
  subCategories?: string[];
  finishings?: string[];
  searchQuery: string;
  setSearchQuery: (val: string) => void;
  selectedCategory: string;
  setSelectedCategory: (val: string) => void;
  showPhysicalOnly: boolean;
  setShowPhysicalOnly: (val: boolean) => void;
  userRole: string;
  requests: ProjectMaterialRequestWithDetails[];
}

export function LibraryTabs({
  vendors,
  materials,
  categories,
  materialCategories = [],
  fixtureCategories = [],
  subCategories = [],
  finishings = [],
  searchQuery,
  setSearchQuery,
  selectedCategory,
  setSelectedCategory,
  showPhysicalOnly,
  setShowPhysicalOnly,
  userRole,
  requests
}: LibraryTabsProps) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();
  
  const currentTab = searchParams.get("tab") || "catalog";
  const [activeTab, setActiveTab] = React.useState(currentTab);
  const [isModalOpen, setIsModalOpen] = React.useState(false);
  const [modalMode, setModalMode] = React.useState<"CREATE" | "EDIT">("CREATE");
  const [selectedData, setSelectedData] = React.useState<LibraryVendor | MaterialCatalogWithRelations | null>(null);

  // Sync state with URL
  React.useEffect(() => {
    setActiveTab(currentTab);
  }, [currentTab]);

  const handleTabChange = (val: string) => {
    const params = new URLSearchParams(searchParams);
    params.set("tab", val);
    router.push(`${pathname}?${params.toString()}`, { scroll: false });
  };

  const retryTab = () => router.refresh();

  const handleSuccess = () => {
    router.refresh(); 
  };

  const handleDeleteMaterial = async (id: string) => {
    if (!confirm("Are you sure you want to delete this material?")) return;
    
    try {
      unwrapActionResult(await deleteMaterialAction({ id }));
      toast.success("Material deleted successfully");
      router.refresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to delete material");
    }
  };

  const handleApproveMaterial = async (id: string) => {
    const material = materials.find(m => m.id === id);
    if (!material) return;
    try {
       unwrapActionResult(await updateMaterialAction({ id, data: { status: "APPROVED" } }));
       toast.success("Material approved and moved to catalog");
       router.refresh();
    } catch (error: unknown) {
       toast.error(error instanceof Error ? error.message : "Failed to approve material");
    }
  };

  const handleRejectMaterial = async (id: string) => {
    try {
       unwrapActionResult(await updateMaterialAction({ id, data: { status: "REJECTED" } }));
       toast.success("Material request rejected");
       router.refresh();
    } catch (error: unknown) {
       toast.error(error instanceof Error ? error.message : "Failed to reject material");
    }
  };

  return (
    <Tabs 
      defaultValue="catalog" 
      value={activeTab} 
      onValueChange={handleTabChange}
      className="w-full"
    >
      <div className="flex flex-col lg:flex-row gap-10 items-start">
        {/* Left Column: Sticky Sidebar (Fixed Width), Project Details Style */}
        <ActionSidebar>
          <ActionSidebarSection title="Library Tools" subtitle="Search & Filters">
              <ActionSidebarItem label="Quick Search">
                 <div className="relative group">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300 group-focus-within:text-slate-900 transition-colors" />
                    <Input
                      placeholder="Find materials..."
                      className="pl-9 w-full bg-white border-slate-200 focus:border-slate-400 focus:ring-0 h-10 font-inter text-sm shadow-none rounded-md transition-all"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                    />
                 </div>
              </ActionSidebarItem>

              <ActionSidebarItem label="Filter Category">
                 <Select value={selectedCategory} onValueChange={setSelectedCategory}>
                    <SelectTrigger className="w-full h-10 border-slate-200 font-inter text-sm focus:ring-0 shadow-none rounded-md transition-all">
                      <div className="flex items-center gap-2">
                        <Filter className="h-3.5 w-3.5 text-slate-400" />
                        <SelectValue placeholder="All Categories" />
                      </div>
                    </SelectTrigger>
                    <SelectContent className="font-inter text-sm rounded-md border-slate-200 shadow-lg">
                      <SelectItem value="all">All Categories</SelectItem>
                      {categories.map((cat) => (
                        <SelectItem key={cat} value={cat}>
                          {cat}
                        </SelectItem>
                      ))}
                    </SelectContent>
                 </Select>
              </ActionSidebarItem>

              <ActionSidebarItem label="Availability">
                 <div className="flex items-center justify-between p-3 bg-slate-50/50 rounded-md border border-slate-100 transition-all hover:border-slate-200">
                    <div className="flex flex-col gap-0.5">
                      <span className="text-[11px] font-bold text-slate-700 font-inter">Physical Only</span>
                      <span className="text-[9px] text-slate-400 font-inter">Hide digital assets</span>
                    </div>
                    <label htmlFor="physical-toggle" className="relative inline-flex items-center cursor-pointer">
                      <input
                        type="checkbox"
                        id="physical-toggle"
                        className="sr-only peer"
                        checked={showPhysicalOnly}
                        onChange={(e) => setShowPhysicalOnly(e.target.checked)}
                      />
                      <div className="w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-slate-900 hover:bg-slate-300"></div>
                    </label>
                 </div>
              </ActionSidebarItem>
          </ActionSidebarSection>

            <Button 
              onClick={() => {
                setModalMode("CREATE");
                setSelectedData(null);
                setIsModalOpen(true);
              }}
              disabled={activeTab === "requests"}
              className="w-full bg-slate-900 hover:bg-slate-800 text-white font-inter text-xs h-11 px-4 rounded-[calc(var(--ui-radius-card,1rem)-0.25rem)] shadow-sm flex items-center justify-center gap-2 transition-all transform hover:scale-[1.02] active:scale-[0.98]"
            >
              <Plus className="h-4 w-4" />
              <span>Add {activeTab === "vendors" ? "Vendor" : "Material"}</span>
            </Button>
        </ActionSidebar>

        {/* Right Column: Dynamic Content Grid (75% on LG) */}
        <main className="flex-1 w-full animate-in fade-in slide-in-from-right-4 duration-1000">
          <div className="flex items-center justify-between mb-8 border-b border-slate-100 pb-4">
             <TabsList className="bg-transparent border-none h-auto p-0 flex gap-6">
                <TabsTrigger value="catalog" className="relative pb-4 rounded-none border-b-2 border-transparent data-[state=active]:border-slate-900 data-[state=active]:bg-transparent shadow-none px-2 transition-all group">
                  <div className="flex items-center gap-2">
                    <LayoutGrid className="h-4 w-4 text-slate-400 group-data-[state=active]:text-slate-900" />
                    <span className="font-lora text-sm md:text-base font-medium text-slate-500 group-data-[state=active]:text-slate-900">Catalog</span>
                  </div>
                </TabsTrigger>
                <TabsTrigger value="inventory" className="relative pb-4 rounded-none border-b-2 border-transparent data-[state=active]:border-slate-900 data-[state=active]:bg-transparent shadow-none px-2 transition-all group">
                  <div className="flex items-center gap-2">
                    <Warehouse className="h-4 w-4 text-slate-400 group-data-[state=active]:text-slate-900" />
                    <span className="font-lora text-sm md:text-base font-medium text-slate-500 group-data-[state=active]:text-slate-900">Inventory</span>
                  </div>
                </TabsTrigger>
                <TabsTrigger value="vendors" className="relative pb-4 rounded-none border-b-2 border-transparent data-[state=active]:border-slate-900 data-[state=active]:bg-transparent shadow-none px-2 transition-all group">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4 text-slate-400 group-data-[state=active]:text-slate-900" />
                    <span className="font-lora text-sm md:text-base font-medium text-slate-500 group-data-[state=active]:text-slate-900">Vendors</span>
                  </div>
                </TabsTrigger>
                
                {(userRole === "ADMIN" || userRole === "STAFF") && (
                  <>
                    <TabsTrigger value="requests" className="relative pb-4 rounded-none border-b-2 border-transparent data-[state=active]:border-slate-900 data-[state=active]:bg-transparent shadow-none px-2 transition-all group shrink-0">
                      <div className="flex items-center gap-2">
                        <ArrowRightCircle className="h-4 w-4 text-slate-400 group-data-[state=active]:text-blue-500" />
                        <span className="font-lora text-sm md:text-base font-medium text-slate-500 group-data-[state=active]:text-slate-900">Requests</span>
                        {requests.filter(r => r.status === 'REQUESTED').length > 0 && (
                          <Badge className="h-4 min-w-[16px] px-1 bg-blue-500 text-white border-none text-[8px] font-black">
                            {requests.filter(r => r.status === 'REQUESTED').length}
                          </Badge>
                        )}
                      </div>
                    </TabsTrigger>
                    <TabsTrigger value="queue" className="relative pb-4 rounded-none border-b-2 border-transparent data-[state=active]:border-slate-900 data-[state=active]:bg-transparent shadow-none px-2 transition-all group shrink-0">
                      <div className="flex items-center gap-2">
                        <div className="relative">
                          <Package className="h-4 w-4 text-slate-400 group-data-[state=active]:text-orange-500" />
                          <span className="absolute -top-1 -right-1 h-1.5 w-1.5 bg-orange-500 rounded-full animate-pulse" />
                        </div>
                        <span className="font-lora text-sm md:text-base font-medium text-slate-500 group-data-[state=active]:text-slate-900 underline decoration-orange-200 decoration-2 underline-offset-4">Queue</span>
                      </div>
                    </TabsTrigger>
                  </>
                )}
             </TabsList>
             
             <div className="hidden lg:flex text-[10px] font-black uppercase tracking-widest text-slate-300">
                {activeTab === "catalog" ? materials.filter(m => m.status === 'APPROVED').length : 
                 activeTab === "queue" ? materials.filter(m => m.status === 'PENDING').length :
                 activeTab === "inventory" ? materials.length :
                 vendors.length} Items Total
             </div>
          </div>

          <TabsContent value="catalog" className="mt-0 focus-visible:outline-none focus-visible:ring-0 min-h-[500px]">
            <ErrorBoundary
              name="Library Catalog"
              fallback={<ErrorFallback title="Catalog Failed" message="Catalog section failed to render." onRetry={retryTab} />}
            >
              <MaterialTable 
                materials={materials.filter(m => m.status === 'APPROVED')}
                userRole={userRole}
                onEdit={(data) => {
                  setModalMode("EDIT");
                  setSelectedData(data);
                  setIsModalOpen(true);
                }}
                onDelete={handleDeleteMaterial}
              />
            </ErrorBoundary>
          </TabsContent>

          <TabsContent value="queue" className="mt-0 focus-visible:outline-none focus-visible:ring-0 min-h-[500px]">
            <div className="mb-6 p-4 bg-orange-50/50 border border-orange-100 rounded-lg flex items-center gap-4 animate-in slide-in-from-top-2 duration-500">
              <div className="h-10 w-10 rounded-full bg-orange-100 flex items-center justify-center shrink-0">
                <Package className="h-5 w-5 text-orange-600" />
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-bold text-orange-900 font-inter">Material Review Queue</span>
                <p className="text-[11px] text-orange-700/80 font-medium font-inter">These items were auto-saved from project schedules or requests. Review and set to &quot;Approved&quot; to finalize in catalog.</p>
              </div>
            </div>

            <ErrorBoundary
              name="Library Queue"
              fallback={<ErrorFallback title="Queue Failed" message="Queue section failed to render." onRetry={retryTab} />}
            >
              <MaterialTable 
                materials={materials.filter(m => m.status === 'PENDING')}
                userRole={userRole}
                isQueueMode={true}
                onApprove={handleApproveMaterial}
                onReject={handleRejectMaterial}
                onEdit={(data) => {
                  setModalMode("EDIT");
                  setSelectedData(data);
                  setIsModalOpen(true);
                }}
                onDelete={handleDeleteMaterial}
              />
            </ErrorBoundary>
          </TabsContent>
          
          <TabsContent value="requests" className="mt-0 focus-visible:outline-none focus-visible:ring-0">
             <ErrorBoundary
               name="Material Requests"
               fallback={<ErrorFallback title="Requests Failed" message="Request table failed to render." onRetry={retryTab} />}
             >
               <MaterialRequestTable 
                 requests={requests}
                 userRole={userRole}
                 onRefresh={() => router.refresh()}
               />
             </ErrorBoundary>
          </TabsContent>

          <TabsContent value="inventory" className="mt-0 focus-visible:outline-none focus-visible:ring-0">
            <ErrorBoundary
              name="Physical Inventory"
              fallback={<ErrorFallback title="Inventory Failed" message="Inventory section failed to render." onRetry={retryTab} />}
            >
              <TableCard>
                <PhysicalInventoryTable 
                  materials={materials} 
                  onEdit={(data) => {
                    setModalMode("EDIT");
                    setSelectedData(data);
                    setIsModalOpen(true);
                  }} 
                />
              </TableCard>
            </ErrorBoundary>
          </TabsContent>

          <TabsContent value="vendors" className="mt-0 focus-visible:outline-none focus-visible:ring-0">
            <ErrorBoundary
              name="Vendor Table"
              fallback={<ErrorFallback title="Vendors Failed" message="Vendor section failed to render." onRetry={retryTab} />}
            >
              <TableCard>
                <VendorTable 
                  vendors={vendors} 
                  onEdit={(data) => {
                    setModalMode("EDIT");
                    setSelectedData(data);
                    setIsModalOpen(true);
                  }} 
                />
              </TableCard>
            </ErrorBoundary>
          </TabsContent>
        </main>
      </div>

      <LibraryFormModal
        isOpen={isModalOpen}
        onOpenChange={setIsModalOpen}
        type={activeTab === "vendors" ? "VENDOR" : "MATERIAL"}
        mode={modalMode}
        initialData={selectedData}
        vendors={vendors}
        categories={categories}
        materialCategories={materialCategories}
        fixtureCategories={fixtureCategories}
        subCategories={subCategories}
        finishings={finishings}
        onSuccess={handleSuccess}
      />
    </Tabs>
  );
}

"use client";

import * as React from "react";
import { MaterialRequestStatus } from "@/generated/prisma";
import type { LucideIcon } from "lucide-react";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { 
  Loader2, 
  Box, 
  History, 
  MoreHorizontal,
  ArrowRightCircle,
  CheckCircle2,
  AlertCircle,
  Link as LinkIcon,
  User as UserIcon
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ProjectMaterialRequestWithDetails } from "../types";
import { updateMaterialRequestStatusAction, deleteProjectMaterialRequestAction } from "../actions/library-actions";
import { unwrapActionResult } from "@/lib/result";
import { toast } from "sonner";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger,
  DropdownMenuLabel,
  DropdownMenuSeparator
} from "@/components/ui/dropdown-menu";

interface MaterialRequestTableProps {
  requests: ProjectMaterialRequestWithDetails[];
  userRole: string;
  onRefresh: () => void;
}

const STATUS_CONFIG: Record<MaterialRequestStatus, { label: string; color: string; icon: LucideIcon }> = {
  REQUESTED: { label: "Requested", color: "bg-blue-50 text-blue-700 border-blue-100", icon: ArrowRightCircle },
  ORDERED: { label: "Ordered", color: "bg-amber-50 text-amber-700 border-amber-100", icon: History },
  SHIPPED: { label: "Shipped", color: "bg-purple-50 text-purple-700 border-purple-100", icon: Box },
  RECEIVED: { label: "Received", color: "bg-emerald-50 text-emerald-700 border-emerald-100", icon: CheckCircle2 },
  UNAVAILABLE: { label: "Unavailable", color: "bg-rose-50 text-rose-700 border-rose-100", icon: AlertCircle },
  CANCELLED: { label: "Cancelled", color: "bg-slate-100 text-slate-700 border-slate-200", icon: AlertCircle },
};

export function MaterialRequestTable({ requests, userRole, onRefresh }: MaterialRequestTableProps) {
  const [updatingId, setUpdatingId] = React.useState<string | null>(null);

  async function handleStatusUpdate(id: string, newStatus: MaterialRequestStatus) {
    setUpdatingId(id);
    try {
      unwrapActionResult(await updateMaterialRequestStatusAction({ id, status: newStatus }));
      toast.success(`Status updated to ${newStatus}`);
      onRefresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to update status");
    } finally {
      setUpdatingId(null);
    }
  }

  async function handleDelete(id: string) {
    if (!confirm("Are you sure you want to delete this request?")) return;
    setUpdatingId(id);
    try {
      unwrapActionResult(await deleteProjectMaterialRequestAction({ id }));
      toast.success("Request deleted");
      onRefresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to delete request");
    } finally {
      setUpdatingId(null);
    }
  }

  if (requests.length === 0) {
    return (
      <div className="py-24 text-center animate-in fade-in duration-500">
        <div className="h-16 w-16 rounded-full bg-slate-50 flex items-center justify-center mx-auto mb-4">
          <Box className="h-6 w-6 text-slate-200" />
        </div>
        <h3 className="font-lora text-lg text-slate-900 mb-1">No requests active</h3>
        <p className="text-sm text-slate-400 font-inter font-medium tracking-tight">Project material requests will appear here for review.</p>
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-slate-100 bg-white overflow-hidden shadow-sm">
      <Table>
        <TableHeader>
          <TableRow className="bg-slate-50/50 hover:bg-slate-50/50 h-14">
            <TableHead className="font-inter font-bold text-[10px] uppercase tracking-wider text-slate-400 pl-6">Project Context</TableHead>
            <TableHead className="font-inter font-bold text-[10px] uppercase tracking-wider text-slate-400">Material Requested</TableHead>
            <TableHead className="font-inter font-bold text-[10px] uppercase tracking-wider text-slate-400">Requestor</TableHead>
            <TableHead className="font-inter font-bold text-[10px] uppercase tracking-wider text-slate-400">Spec Status</TableHead>
            <TableHead className="font-inter font-bold text-[10px] uppercase tracking-wider text-slate-400 text-right pr-6">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {requests.map((req) => {
            const config = STATUS_CONFIG[req.status] || STATUS_CONFIG.REQUESTED;
            const StatusIcon = config.icon;
            const mat = req.material;

            return (
              <TableRow key={req.id} className="hover:bg-slate-50/30 group transition-colors border-slate-50 min-h-[70px]">
                <TableCell className="pl-6">
                  <div className="flex flex-col gap-0.5">
                    <span className="text-xs font-inter font-bold text-slate-900 truncate max-w-[150px]">
                      {req.project.name}
                    </span>
                    <span className="text-[10px] text-slate-400 font-inter flex items-center gap-1">
                      <MapPin className="h-2.5 w-2.5" />
                      {req.area_location || "Universal"}
                    </span>
                  </div>
                </TableCell>
                <TableCell>
                  <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-md bg-slate-50 overflow-hidden flex-shrink-0 border border-slate-100">
                      {mat?.catalog_image_url ? (
                        <img src={mat.catalog_image_url} alt={mat.catalog_sku} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-200">
                          <Box className="h-4 w-4" />
                        </div>
                      )}
                    </div>
                    <div className="flex flex-col">
                      <span className="font-lora font-medium text-slate-900 text-xs">
                        {mat?.catalog_sku || req.custom_material_name || "Custom Material"}
                        {!mat && <Badge className="ml-2 bg-amber-50 text-amber-600 border-none text-[8px] h-4 px-1">Manual</Badge>}
                      </span>
                      <span className="text-[10px] text-slate-400 font-inter uppercase tracking-widest font-bold">
                        {mat?.catalog_brand || mat?.vendor?.brand_name || "Custom Source"}
                      </span>
                    </div>
                  </div>
                </TableCell>
                <TableCell>
                  <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-slate-700 font-inter font-semibold text-xs">
                       <UserIcon className="h-3 w-3 text-slate-300" />
                       {req.requested_by.name}
                    </div>
                    <span className="text-[9px] text-slate-400 font-inter">
                      {new Intl.DateTimeFormat("id-ID", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(req.created_at))}
                    </span>
                  </div>
                </TableCell>
                <TableCell>
                  <div className="flex flex-col gap-1.5">
                    <Badge className={`w-fit rounded-lg font-bold border-none ${config.color} px-2 py-0.5 text-[9px] uppercase tracking-widest flex items-center gap-1.5 shadow-none`}>
                      <StatusIcon className="h-2.5 w-2.5" />
                      {config.label}
                    </Badge>
                    {req.status === "RECEIVED" && (
                      <span className="text-[9px] text-emerald-600 font-bold font-inter ml-1">
                        By {req.staff_name_override || "Admin"}
                      </span>
                    )}
                  </div>
                </TableCell>
                <TableCell className="text-right pr-6">
                  <div className="flex justify-end gap-1">
                    {req.reference_url && (
                        <Button
                          variant="ghost"
                          size="sm"
                          asChild
                          className="h-8 w-8 p-0 text-slate-400 hover:text-slate-900"
                        >
                          <a href={req.reference_url} target="_blank" rel="noopener noreferrer">
                            <LinkIcon className="h-4 w-4" />
                          </a>
                        </Button>
                    )}
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button 
                          variant="ghost" 
                          size="sm" 
                          className="h-8 w-8 p-0 text-slate-400 hover:text-slate-900 rounded-lg hover:bg-slate-100 transition-colors"
                          disabled={updatingId === req.id}
                        >
                          {updatingId === req.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <MoreHorizontal className="h-4 w-4" />}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-[180px] rounded-xl shadow-2xl border-slate-100 p-2 font-inter bg-white">
                        <DropdownMenuLabel className="text-[10px] uppercase tracking-[0.2em] text-slate-400 font-black px-2 py-2">Set Status</DropdownMenuLabel>
                        <DropdownMenuSeparator className="bg-slate-50" />
                        {(Object.keys(STATUS_CONFIG) as MaterialRequestStatus[]).map((status) => (
                          <DropdownMenuItem 
                            key={status}
                            onClick={() => handleStatusUpdate(req.id, status)}
                            className="rounded-lg cursor-pointer focus:bg-slate-50 py-1.5"
                          >
                            <div className="flex items-center gap-2.5">
                              <div className={`h-1.5 w-1.5 rounded-full ${STATUS_CONFIG[status].color.split(" ")[0]}`} />
                              <span className="text-[11px] font-bold text-slate-700 uppercase tracking-tight">{STATUS_CONFIG[status].label}</span>
                            </div>
                          </DropdownMenuItem>
                        ))}
                        {(userRole === "ADMIN" || userRole === "STAFF") && (
                          <>
                            <DropdownMenuSeparator className="bg-slate-50" />
                            <DropdownMenuItem 
                              onClick={() => handleDelete(req.id)}
                              className="rounded-lg cursor-pointer text-rose-500 focus:bg-rose-50 focus:text-rose-600 py-1.5 font-bold text-[11px]"
                            >
                               Delete Request
                            </DropdownMenuItem>
                          </>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
}

// Helper icons
function MapPin(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      {...props}
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" />
      <circle cx="12" cy="10" r="3" />
    </svg>
  );
}

"use client";

import * as React from "react";
import {
