"use client";

import * as React from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { 
  Box, 
  MapPin, 
  Pencil, 
  Trash2, 
  Loader2 
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { MaterialCatalogWithRelations } from "../types";
import { deleteMaterialAction } from "../actions/library-actions";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { unwrapActionResult } from "@/lib/result";
import { useRouter } from "next/navigation";

interface PhysicalInventoryTableProps {
  materials: MaterialCatalogWithRelations[];
  onEdit: (material: MaterialCatalogWithRelations) => void;
}

type FlattenedSampleRow = {
  id: string;
  location_rak: string;
  container_box: string;
  notes: string;
  material: MaterialCatalogWithRelations;
};

export function PhysicalInventoryTable({ materials, onEdit }: PhysicalInventoryTableProps) {
  const router = useRouter();
  const [deletingId, setDeletingId] = React.useState<string | null>(null);

  // Flattened view for auditing
  const flattenedSamples = React.useMemo(() => {
    return materials.map(m => {
      // Prioritize top-level fields if filled, otherwise fallback to physical_samples
      if (m.catalog_rak_location || m.catalog_box_number) {
        return { 
          id: `flat-${m.id}`, 
          location_rak: m.catalog_rak_location || "-", 
          container_box: m.catalog_box_number || "-", 
          notes: m.physical_samples?.[0]?.notes || "-", 
          material: m 
        };
      }
      
      const sample = m.physical_samples?.[0];
      return {
        id: sample?.id || `no-sample-${m.id}`,
        location_rak: sample?.location_rak || "-",
        container_box: sample?.container_box || "-",
        notes: sample?.notes || "-",
        material: m
      };
    });
  }, [materials]);

  async function handleDelete(id: string) {
    if (!confirm("Are you sure you want to delete this material?")) return;
    setDeletingId(id);
    try {
      unwrapActionResult(await deleteMaterialAction({ id }));
      toast.success("Material deleted successfully");
      router.refresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to delete material");
    } finally {
      setDeletingId(null);
    }
  }

  if (materials.length === 0) {
    return (
      <div className="py-12 text-center text-slate-400 font-inter text-sm">
        No physical samples in inventory.
      </div>
    );
  }

  return (
    <div className="rounded-md border border-slate-100 bg-white overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow className="bg-slate-50/50 hover:bg-slate-50/50">
            <TableHead className="font-inter font-semibold text-slate-900">Rak / Box</TableHead>
            <TableHead className="font-inter font-semibold text-slate-900">Material Info</TableHead>
            <TableHead className="font-inter font-semibold text-slate-900">Vendor</TableHead>
            <TableHead className="font-inter font-semibold text-slate-900">Notes</TableHead>
            <TableHead className="font-inter font-semibold text-slate-900 text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {flattenedSamples.map((row: FlattenedSampleRow) => (
            <TableRow key={row.id} className="hover:bg-slate-50/30 group h-12">
              <TableCell className="w-[200px]">
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-1.5 text-xs text-slate-700 bg-slate-100 px-2 py-1 rounded font-bold font-inter">
                    <MapPin className="h-3 w-3 text-slate-400" />
                    <span>Rak {row.location_rak}</span>
                  </div>
                  <div className="flex items-center gap-1.5 text-xs text-slate-700 bg-slate-100 px-2 py-1 rounded font-bold font-inter">
                    <Box className="h-3 w-3 text-slate-400" />
                    <span>Box {row.container_box}</span>
                  </div>
                </div>
              </TableCell>
              <TableCell>
                <div className="flex flex-col">
                  <div className="font-lora font-medium text-slate-900 text-sm">
                    {row.material.catalog_sku}
                  </div>
                  <div className="text-[10px] text-slate-400 uppercase tracking-wider font-bold">
                    {row.material.catalog_category} {row.material.catalog_sub_category ? `// ${row.material.catalog_sub_category}` : ""}
                  </div>
                </div>
              </TableCell>
              <TableCell className="text-sm font-medium text-slate-500 font-inter">
                 {row.material.vendor.brand_name}
              </TableCell>
              <TableCell className="text-xs text-slate-400 italic max-w-[200px] truncate">
                {row.notes}
              </TableCell>
              <TableCell className="text-right">
                <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onEdit(row.material)}
                    className="h-8 w-8 p-0 text-slate-400 hover:text-slate-900"
                  >
                    <Pencil className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDelete(row.material.id)}
                    disabled={deletingId === row.material.id}
                    className="h-8 w-8 p-0 text-slate-400 hover:text-rose-600"
                  >
                    {deletingId === row.material.id ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Trash2 className="h-4 w-4" />
                    )}
                  </Button>
                </div>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Search, Loader2, Plus, Box, MapPin, ImageIcon, CheckCircle2, Building2 } from "lucide-react";

import { getMaterialsAction, createProjectMaterialRequestAction } from "../actions/library-actions";
import { MaterialCatalogWithRelations } from "../types";
import { unwrapActionResult } from "@/lib/result";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { CreatableSearch } from "@/components/ui/creatable-search";
import { UniversalImageUploader } from "@/components/ui/universal-image-uploader";

interface ProjectMaterialRequestModalProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  projectId: string;
  onSuccess?: () => void;
}

export function ProjectMaterialRequestModal({
  isOpen,
  onOpenChange,
  projectId,
  onSuccess,
}: ProjectMaterialRequestModalProps) {
  const [materials, setMaterials] = React.useState<MaterialCatalogWithRelations[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [submitting, setSubmitting] = React.useState(false);
  const [selectedMaterialId, setSelectedMaterialId] = React.useState<string | null>(null);
  const [isManualEntry, setIsManualEntry] = React.useState(false);
  const [customName, setCustomName] = React.useState("");
  const [referenceUrl, setReferenceUrl] = React.useState("");
  const [search, setSearch] = React.useState("");
  const [notes, setNotes] = React.useState("");
  const [areaLocation, setAreaLocation] = React.useState("");
  const [coverUrl, setCoverUrl] = React.useState("");
  const [originalUrl, setOriginalUrl] = React.useState("");

  const fetchMaterials = React.useCallback(async () => {
    setLoading(true);
    try {
      const result = unwrapActionResult(await getMaterialsAction({ search, status: 'APPROVED' }));
      setMaterials(result);
    } catch (error) {
      toast.error("Failed to fetch library catalog");
    } finally {
      setLoading(false);
    }
  }, [search]);

  React.useEffect(() => {
    if (!isOpen) {
      setSearch("");
      setNotes("");
      setAreaLocation("");
      setCustomName("");
      setReferenceUrl("");
      setCoverUrl("");
      setOriginalUrl("");
    }
    if (isOpen) {
      fetchMaterials();
    }
  }, [isOpen, fetchMaterials]);

  async function handleSubmit() {
    if (!isManualEntry && !selectedMaterialId) {
      toast.error("Please select a material first or use Manual Entry");
      return;
    }

    if (isManualEntry && !customName.trim()) {
      toast.error("Please enter a material name for manual entry");
      return;
    }
    
    setSubmitting(true);
    try {
      unwrapActionResult(await createProjectMaterialRequestAction({
        project_id: projectId,
        material_id: isManualEntry ? undefined : (selectedMaterialId || undefined),
        custom_material_name: isManualEntry ? customName.trim() : undefined,
        reference_url: isManualEntry ? referenceUrl.trim() : undefined,
        cover_url: isManualEntry ? coverUrl : undefined,
        original_url: isManualEntry ? originalUrl : undefined,
        area_location: areaLocation || undefined,
        is_scheduled: true, // Default to true as per requirements
        notes: notes || undefined
      }));
      toast.success("Material added to schedule");
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to add to schedule");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[800px] max-h-[85vh] flex flex-col p-0 overflow-hidden border-none shadow-2xl">
        <DialogHeader className="p-6 border-b border-slate-100 bg-white">
          <DialogTitle className="font-lora text-2xl font-medium">Request Project Material</DialogTitle>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-xs text-slate-400 font-inter uppercase tracking-widest">
              Standardized procurement workflow
            </p>
            <span className="text-[10px] bg-emerald-50 text-emerald-600 font-black px-1.5 py-0.5 rounded uppercase tracking-tighter" title="Suggested from global archives.">
              Library Suggester
            </span>
          </div>
          
          <div className="mt-6 space-y-4">
             <div className="space-y-2">
                <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Search Catalog or Type Custom *</Label>
                <CreatableSearch
                  options={materials.map(m => ({ 
                    id: m.id, 
                    name: `${m.catalog_product_name} • ${m.vendor?.brand_name || "Custom"}`,
                    badge: m.status === 'APPROVED' ? "Gold" : "Queue"
                  }))}
                  value={selectedMaterialId || undefined}
                  onSelect={(id, name) => {
                    setSelectedMaterialId(id);
                    setIsManualEntry(false);
                    setCustomName("");
                  }}
                  onCreate={(name) => {
                    setSelectedMaterialId(null);
                    setIsManualEntry(true);
                    setCustomName(name);
                  }}
                  onSearchChange={setSearch}
                  placeholder="Search by brand, type, or motif..."
                  allowFreeText
                />
                {isManualEntry && (
                   <div className="animate-in fade-in slide-in-from-top-1 duration-300">
                      <Badge className="bg-amber-50 text-amber-600 border-amber-100 py-1 px-2 pointer-events-none lowercase font-inter italic tracking-normal">
                        Ready for manual entry: &quot;{customName}&quot;
                      </Badge>
                   </div>
                )}
             </div>

             <div className="flex flex-col md:flex-row gap-4">
               <div className="flex-1 space-y-2">
                 <Label htmlFor="area_location" className="text-[10px] font-black uppercase tracking-widest text-slate-400">Area / Location in Project</Label>
                 <Input
                   id="area_location"
                   placeholder="e.g. Master Bedroom, Dining Wall Area"
                   className="bg-slate-50 border-none h-11 focus:ring-slate-900 text-sm font-inter"
                   value={areaLocation}
                   onChange={(e) => setAreaLocation(e.target.value)}
                 />
               </div>
               <div className="flex-1 space-y-2">
                 <Label htmlFor="notes" className="text-[10px] font-black uppercase tracking-widest text-slate-400">Contextual Notes (Optional)</Label>
                 <Input
                   id="notes"
                   placeholder="e.g. Needs sample for client meeting"
                   className="bg-slate-50 border-none h-11 focus:ring-slate-900 text-sm font-inter"
                   value={notes}
                   onChange={(e) => setNotes(e.target.value)}
                 />
               </div>
             </div>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-2">
          {isManualEntry && (
            <div className="py-6 space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="md:col-span-1">
                      <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Visual Reference</Label>
                      <UniversalImageUploader
                        initialImageUrl={null}
                        onUploadComplete={({ original, cover }) => {
                          setCoverUrl(cover);
                          setOriginalUrl(original);
                        }}
                        label="Add Photo"
                      />
                  </div>
                  <div className="md:col-span-2 space-y-6">
                      <div className="space-y-2">
                          <Label htmlFor="custom_name" className="text-[10px] font-black uppercase tracking-widest text-slate-400">Custom Material Name & Brand</Label>
                          <Input
                            id="custom_name"
                            placeholder="e.g. Roman Tile Granit G6022..."
                            className="bg-white border-2 border-slate-100 focus:border-slate-900 h-12 text-sm font-medium transition-all"
                            value={customName}
                            onChange={(e) => setCustomName(e.target.value)}
                          />
                      </div>
                      <div className="space-y-2">
                          <Label htmlFor="ref_url" className="text-[10px] font-black uppercase tracking-widest text-slate-400">Reference Link (Tokopedia/Website)</Label>
                          <Input
                            id="ref_url"
                            placeholder="https://www.tokopedia.com/product..."
                            className="bg-white border-2 border-slate-100 focus:border-slate-900 h-12 text-sm font-inter transition-all"
                            value={referenceUrl}
                            onChange={(e) => setReferenceUrl(e.target.value)}
                          />
                      </div>
                  </div>
               </div>
            </div>
          )}

          {!isManualEntry && selectedMaterialId && (
            <div className="py-6 animate-in zoom-in-95 duration-300">
{materials.filter(m => m.id === selectedMaterialId).map(m => (
                  <div key={m.id} className="flex items-start gap-6 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 shadow-sm transition-all hover:shadow-md">
                     <div className="h-24 w-24 rounded-2xl bg-white shadow-inner overflow-hidden flex-shrink-0 border border-slate-100">
                       {m.catalog_image_url ? (
                         <img src={m.catalog_image_url || ""} alt={m.catalog_product_name || ""} className="w-full h-full object-cover" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center">
                           <ImageIcon className="h-8 w-8 text-slate-200" />
                         </div>
                       )}
                     </div>
                     <div className="flex-1 space-y-2">
                        <div className="flex items-center justify-between">
                           <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Catalog Match</span>
                           {m.status === 'APPROVED' ? (
                             <Badge className="bg-emerald-50 text-emerald-600 border-none font-black text-[8px] uppercase px-1.5 h-4">Gold Standard</Badge>
                           ) : (
                             <Badge className="bg-slate-200 text-slate-600 border-none font-black text-[8px] uppercase px-1.5 h-4">In Queue</Badge>
                           )}
                        </div>
                        <h3 className="font-lora text-xl font-medium text-slate-900">{m.catalog_product_name}</h3>
                        <div className="flex items-center gap-2 text-xs font-inter text-slate-500">
                           <Building2 className="h-3 w-3" />
                           <span>{m.vendor?.brand_name || "Custom / Bespoke"}</span>
                        </div>
                        {m.catalog_sub_category && (
                          <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-tighter text-slate-400 pt-1">
                             <Plus className="h-3 w-3" />
                             <span>{m.catalog_sub_category}</span>
                          </div>
                        )}
                    </div>
                    <div className="pt-1">
                       <CheckCircle2 className="h-6 w-6 text-emerald-500" />
                    </div>
                 </div>
               ))}
            </div>
          )}

          {!isManualEntry && !selectedMaterialId && (
            <div className="py-20 text-center opacity-30 flex flex-col items-center gap-4 animate-in fade-in duration-500">
               <div className="h-16 w-16 rounded-full bg-slate-100 flex items-center justify-center">
                  <Search className="h-6 w-6 text-slate-400" />
               </div>
               <p className="text-sm font-medium font-inter">Search the archives to fetch material specs...</p>
            </div>
          )}
        </div>

        <DialogFooter className="p-6 border-t border-slate-100 bg-slate-50 mt-auto flex items-center justify-end">
          <Button 
            variant="ghost" 
            onClick={() => onOpenChange(false)}
            className="text-slate-500 hover:text-slate-900 font-inter text-sm"
          >
            Cancel
          </Button>
          <Button 
            onClick={handleSubmit}
            disabled={(!isManualEntry && !selectedMaterialId) || (isManualEntry && !customName.trim()) || submitting}
            className="bg-slate-900 hover:bg-slate-800 text-white rounded-xl h-11 px-8 shadow-lg shadow-slate-200 font-inter text-xs uppercase tracking-widest font-bold ml-2"
          >
            {submitting ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
            Submit Request
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { Loader2, Upload, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { unwrapActionResult } from "@/lib/result";
import { toast } from "sonner";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScheduleSection } from "@/generated/prisma";
import { 
  getProjectScheduleAction, 
  importScheduleAction,
  reorderScheduleEntriesAction,
  bulkDeleteScheduleEntriesAction,
} from "@/actions/schedule-actions";
import { ScheduleCategorySection } from "./ScheduleCategorySection";
import { ScheduleSearchBar } from "./ScheduleSearchBar";
import { ScheduleMaterialPickerModal } from "./ScheduleMaterialPickerModal";
import { ScheduleSpecEditorModal } from "./ScheduleSpecEditorModal";
import type { ProjectScheduleSheetPayload } from "../types";
import { ErrorBoundary } from "@/components/shared/error-boundary";
import { ErrorFallback } from "@/components/shared/error-fallback";
import { ProjectScheduleProvider } from "../context/ProjectScheduleContext";
import { PageHeader, TableCard } from "@/ui_engine";

import { 
  TableHeader, 
  TableHead,
  TableRow 
} from "@/components/ui/table";
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from "@dnd-kit/core";
import {
  arrayMove,
  sortableKeyboardCoordinates,
} from "@dnd-kit/sortable";

interface ProjectScheduleMainProps {
  projectId: string;
}

export function ProjectScheduleMain({
  projectId,
}: ProjectScheduleMainProps) {
  const [sheet, setSheet] = React.useState<ProjectScheduleSheetPayload | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [activeSection, setActiveSection] = React.useState<ScheduleSection>(ScheduleSection.MATERIAL);
  const [importing, setImporting] = React.useState(false);
  const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set());
  const [selectionAnchorId, setSelectionAnchorId] = React.useState<string | null>(null);
  
  const containerRef = React.useRef<HTMLDivElement>(null);
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  // Modal Hosting State
  const [pickerModal, setPickerModal] = React.useState<{ 
    isOpen: boolean; 
    entryId?: string;
    category?: string;
    section?: ScheduleSection;
  }>({ 
    isOpen: false 
  });

  const [editorModal, setEditorModal] = React.useState<{ 
    isOpen: boolean; 
    optionId: string; 
    initialSnapshot: import("../types").ScheduleOptionSnapshot;
  } | null>(null);

  const fetchSchedule = React.useCallback(async (section: ScheduleSection) => {
    setLoading(true);
    try {
      const result = unwrapActionResult(await getProjectScheduleAction({
        projectId,
        section,
      }));
      setSheet(result as ProjectScheduleSheetPayload);
      // Clear selection on section change or full refresh? 
      // User says "click outside", but refresh usually stays unless items are gone.
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to fetch schedule");
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  // Click away to deselect & ESC key
  React.useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        // Only clear if not clicking on a modal/dropdown that might be outside the container
        const isOutside = !containerRef.current.contains(e.target as Node);
        const isModal = (e.target as HTMLElement).closest('[role="dialog"]');
        const isAction = (e.target as HTMLElement).closest('[data-selection-ignore="true"]');
        
        if (isOutside && !isModal && !isAction) {
          setSelectedIds(new Set());
          setSelectionAnchorId(null);
        }
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setSelectedIds(new Set());
        setSelectionAnchorId(null);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  const handleRowClick = (id: string, event: React.MouseEvent) => {
    const isShift = event.shiftKey;
    const isCtrl = event.ctrlKey || event.metaKey;

    if (!sheet) return;

    // Flatten all entries across categories to allow range select
    const allEntries = sheet.groups.flatMap(g => g.entries);
    const ids = allEntries.map(e => e.id);

    if (isShift && selectionAnchorId) {
      const start = ids.indexOf(selectionAnchorId);
      const end = ids.indexOf(id);
      
      if (start === -1 || end === -1) {
        setSelectedIds(new Set([id]));
        setSelectionAnchorId(id);
        return;
      }

      const range = ids.slice(Math.min(start, end), Math.max(start, end) + 1);
      const next = new Set(isCtrl ? selectedIds : []);
      range.forEach(rid => next.add(rid));
      setSelectedIds(next);
      // Anchor stays the same for shift selection to allow range adjustment
    } else if (isCtrl) {
      const next = new Set(selectedIds);
      if (next.has(id)) {
        next.delete(id);
        // If we unselected the anchor, update it to the last remaining item or null
        if (id === selectionAnchorId) {
          setSelectionAnchorId(Array.from(next).pop() || null);
        }
      } else {
        next.add(id);
        setSelectionAnchorId(id);
      }
      setSelectedIds(next);
    } else {
      setSelectedIds(new Set([id]));
      setSelectionAnchorId(id);
    }
  };

  const handleRefresh = React.useCallback(() => {
    fetchSchedule(activeSection);
  }, [fetchSchedule, activeSection]);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id || !sheet) return;

    // Find which group contains the active and over items
    const activeGroup = sheet.groups.find(g => g.entries.some(e => e.id === active.id));
    const overGroup = sheet.groups.find(g => g.entries.some(e => e.id === over.id));

    // Only allow reordering within the same category
    if (!activeGroup || !overGroup || activeGroup.schedule_category !== overGroup.schedule_category) return;

    const entries = activeGroup.entries;
    const oldIndex = entries.findIndex((item) => item.id === active.id);
    const newIndex = entries.findIndex((item) => item.id === over.id);
    
    const newArray = arrayMove(entries, oldIndex, newIndex);
    const updateData = newArray.map((item, index) => ({
      id: item.id,
      schedule_sort_order: index + 1
    }));

    try {
      unwrapActionResult(await reorderScheduleEntriesAction({
        projectId: projectId,
        section: activeSection,
        category: activeGroup.schedule_category,
        items: updateData
      }));
      fetchSchedule(activeSection);
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : "Failed to reorder items");
    }
  };

  const handleBulkDelete = async () => {
    if (!sheet || selectedIds.size === 0) return;
    
    const confirm = window.confirm(`Are you sure you want to delete ${selectedIds.size} selected items?`);
    if (!confirm) return;

    const toastId = toast.loading(`Deleting ${selectedIds.size} items...`);
    setLoading(true);
    try {
      // Group selected IDs by category
      const entriesByGroup: Record<string, string[]> = {};
      sheet.groups.forEach(g => {
        const idsInGroup = g.entries
          .filter(e => selectedIds.has(e.id))
          .map(e => e.id);
        if (idsInGroup.length > 0) {
          entriesByGroup[g.schedule_category] = idsInGroup;
        }
      });

      // Execute bulk delete for each group
      for (const [category, ids] of Object.entries(entriesByGroup)) {
        unwrapActionResult(await bulkDeleteScheduleEntriesAction({
          projectId,
          section: activeSection,
          category,
          entryIds: ids
        }));
      }

      toast.success(`Deleted ${selectedIds.size} items`, { id: toastId });
      setSelectedIds(new Set());
      fetchSchedule(activeSection);
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Bulk delete failed");
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    fetchSchedule(activeSection);
  }, [fetchSchedule, activeSection]);

  const groups = sheet?.groups ?? [];

  const handleImport = React.useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    
    setImporting(true);
    try {
      const content = await file.text();
      const result = unwrapActionResult(await importScheduleAction({
        projectId,
        section: activeSection,
        csvContent: content,
        source: "gsheets",
      })) as { created: number; updated: number };
      
      toast.success(`Imported ${result.created} new rows, updated ${result.updated} existing rows`);
      fetchSchedule(activeSection);
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to import CSV");
    } finally {
      setImporting(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    }
  }, [projectId, activeSection, fetchSchedule]);

  if (loading && !sheet) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-10 w-10 animate-spin text-slate-200" />
      </div>
    );
  }

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <PageHeader
        eyebrow="Specifications"
        title="Material & Fixtures Schedule"
        description="Detailed procurement and technical schedule."
        titleClassName="font-lora text-4xl normal-case tracking-tight text-slate-900"
        descriptionClassName="mt-1 font-inter text-sm text-slate-500 max-w-2xl"
        className="pb-2"
        action={
          <div className="flex items-center gap-3 relative">
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv"
              className="hidden"
              onChange={handleImport}
              disabled={importing}
            />
            
            {selectedIds.size > 0 && (
              <Button
                variant="ghost"
                data-selection-ignore="true"
                onMouseDown={(e) => e.stopPropagation()}
                className="h-11 rounded-xl text-xs font-bold text-red-600 bg-transparent hover:bg-red-50 px-4 transition-all"
                onClick={handleBulkDelete}
              >
                Delete Selected ({selectedIds.size})
              </Button>
            )}


            <Button
              variant="outline"
              data-selection-ignore="true"
              onMouseDown={(e) => e.stopPropagation()}
              className="h-11 rounded-xl border-slate-200 text-xs font-semibold text-slate-600"
              onClick={() => fileInputRef.current?.click()}
              disabled={importing}
            >
              {importing ? <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" /> : <Upload className="mr-2 h-3.5 w-3.5" />}
              Import CSV
            </Button>
          </div>
        }
      />

      <Tabs
        defaultValue={ScheduleSection.MATERIAL}
        value={activeSection}
        onValueChange={(value) => setActiveSection(value as ScheduleSection)}
        className="w-full"
      >
        <TabsList className="h-12 w-full max-w-md rounded-xl border border-slate-200/60 bg-slate-100/50 p-1">
          <TabsTrigger
            value={ScheduleSection.MATERIAL}
            className="flex-1 rounded-lg py-2 text-[10px] font-bold uppercase tracking-wider text-slate-400 transition-all data-[state=active]:bg-white data-[state=active]:text-slate-900 data-[state=active]:shadow-sm"
          >
            Material Schedule
          </TabsTrigger>
          <TabsTrigger
            value={ScheduleSection.FIXTURE}
            className="flex-1 rounded-lg py-2 text-[10px] font-bold uppercase tracking-wider text-slate-400 transition-all data-[state=active]:bg-white data-[state=active]:text-slate-900 data-[state=active]:shadow-sm"
          >
            Fixtures Schedule
          </TabsTrigger>
        </TabsList>

        <div className="mt-6">
          <ScheduleSearchBar 
            projectId={projectId}
            section={activeSection}
            onSuccess={handleRefresh}
          />
        </div>

        <div ref={containerRef} className="mt-6 w-full">
          <DndContext 
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <TableCard className="w-full">
              <TableHeader className="sticky top-0 z-30 bg-white border-b border-slate-200">
                <TableRow className="hover:bg-transparent transition-none border-b border-slate-100">
                  <TableHead className="w-20 px-4 py-2 text-slate-400 text-[10px] font-medium uppercase tracking-wider text-center">Code</TableHead>
                  <TableHead className="w-16 px-4 py-2 text-slate-400 text-[10px] font-medium uppercase tracking-wider text-center">Image</TableHead>
                  <TableHead className="flex-1 px-4 py-2 text-slate-400 text-[10px] font-medium uppercase tracking-wider">Product Information</TableHead>
                  <TableHead className="w-32 px-4 py-2 text-slate-400 text-[10px] font-medium uppercase tracking-wider">Location</TableHead>
                  <TableHead className="w-16 px-4 py-2 text-right"></TableHead>
                </TableRow>
              </TableHeader>

              {groups.map((group) => (
                <ErrorBoundary
                  key={group.schedule_category}
                  name={`Schedule ${group.schedule_category}`}
                  fallback={
                    <tbody>
                      <tr>
                        <td colSpan={11} className="p-4">
                          <ErrorFallback
                            title={`Failed to render ${group.schedule_category}`}
                            message="Please retry loading this category section."
                            onRetry={() => fetchSchedule(activeSection)}
                          />
                        </td>
                      </tr>
                    </tbody>
                  }
                >
                  <ScheduleCategorySection
                    projectId={projectId}
                    category={group.schedule_category}
                    section={group.schedule_section}
                    entries={group.entries}
                    onRefresh={() => fetchSchedule(activeSection)}
                    selectedIds={selectedIds}
                    onRowClick={handleRowClick}
                    onClearSelection={() => {
                       setSelectedIds(new Set());
                       setSelectionAnchorId(null);
                    }}
                    openPicker={(entryId) => setPickerModal({ 
                      isOpen: true, 
                      entryId,
                      category: group.schedule_category,
                      section: activeSection
                    })}

                    openEditor={(optionId, snapshot) => setEditorModal({ isOpen: true, optionId, initialSnapshot: snapshot })}
                  />
                </ErrorBoundary>
              ))}
            </TableCard>
          </DndContext>
        </div>
      </Tabs>

      {/* Hoisted Modals */}
      {pickerModal.isOpen && pickerModal.category && pickerModal.section && (
        <ProjectScheduleProvider
          value={{
            projectId,
            category: pickerModal.category,
            section: pickerModal.section,
            onSuccess: handleRefresh
          }}
        >
          <ScheduleMaterialPickerModal
            entryId={pickerModal.entryId}
            isOpen={pickerModal.isOpen}
            onOpenChange={(open) => setPickerModal({ ...pickerModal, isOpen: open })}
          />
        </ProjectScheduleProvider>
      )}



      {editorModal && (
        <ScheduleSpecEditorModal
          optionId={editorModal.optionId}
          initialSnapshot={editorModal.initialSnapshot}
          isOpen={editorModal.isOpen}
          onOpenChange={(open) => setEditorModal(open ? editorModal : null)}
          onRefresh={handleRefresh}
        />
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { ScheduleSection } from "@/generated/prisma";
import { 
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { Button } from "@/components/ui/button";
import { ProjectScheduleEntryWithRelations } from "../types";
import { ScheduleEntryRow } from "./ScheduleEntryRow";
import { addScheduleEntryInstantAction, bulkDeleteScheduleEntriesAction } from "@/actions/schedule-actions";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import { 
  TableBody, 
  TableCell, 
  TableRow 
} from "@/components/ui/table";
import { ChevronDown, ChevronRight, Trash2, AlertCircle } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface ScheduleCategorySectionProps {
  projectId: string;
  category: string;
  section: ScheduleSection;
  entries: ProjectScheduleEntryWithRelations[];
  onRefresh: () => void;
  selectedIds: Set<string>;
  onRowClick: (id: string, event: React.MouseEvent) => void;
  onClearSelection: () => void;
  openPicker: (entryId: string) => void;
  openEditor: (optionId: string, snapshot: import("../types").ScheduleOptionSnapshot) => void;
}

export function ScheduleCategorySection({ 
  projectId, 
  category, 
  section,
  entries,
  onRefresh,
  selectedIds,
  onRowClick,
  onClearSelection,
  openPicker,
  openEditor
}: ScheduleCategorySectionProps) {
  const [isCollapsed, setIsCollapsed] = React.useState(false);

  return (
    <>
      <TableBody className="group/section">
        <TableRow className="bg-white hover:bg-white border-b border-slate-200 z-20 sticky top-[49px]">
          <TableCell colSpan={5} className="px-4 py-6 align-middle">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6 cursor-pointer group/title" onClick={() => setIsCollapsed(!isCollapsed)}>
                <div className="flex items-center justify-center h-8 w-8 rounded-lg bg-white shadow-sm border border-slate-100 text-slate-400 group-hover/title:text-slate-900 group-hover/title:border-slate-300 transition-all">
                  {isCollapsed ? <ChevronRight className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                </div>
                <div className="flex items-center gap-4">
                  <h4 className="font-lora text-lg font-bold text-slate-900 tracking-tight uppercase">{category}</h4>
                  <div className="h-1 w-1 rounded-full bg-slate-300" />
                  <span className="font-inter text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    {entries.length} items
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-3">
              </div>
            </div>
          </TableCell>
        </TableRow>

        {!isCollapsed && (
          <SortableContext 
            items={entries.map(e => e.id)}
            strategy={verticalListSortingStrategy}
          >
            {entries.map((entry) => (
              <ScheduleEntryRow 
                key={entry.id} 
                entry={entry} 
                onRefresh={onRefresh}
                isSelected={selectedIds.has(entry.id)}
                onSelect={(e) => onRowClick(entry.id, e)}
                openPicker={openPicker}
                openEditor={openEditor}
              />
            ))}
          </SortableContext>
        )}
      </TableBody>
    </>
  );
}

"use client";

import * as React from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  GripVertical,
  MoreHorizontal,
  Trash2,
  Plus,
  Loader2,
  FileUp,
  Globe,
  ChevronUp,
  ChevronDown
} from "lucide-react";
import { TableCell, TableRow } from "@/components/ui/table";
import { ImageLightbox } from "@/components/ui/image-lightbox";
import { Button } from "@/components/ui/button";
import { 
  deleteScheduleEntryAction, 
  updateScheduleOptionSnapshotAction, 
  promoteToLibraryAction 
} from "@/actions/schedule-actions";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ProjectScheduleEntryWithRelations, ScheduleOptionSnapshot } from "../types";
import { ScheduleMaterialPickerModal } from "./ScheduleMaterialPickerModal";
import { ScheduleSpecEditorModal } from "./ScheduleSpecEditorModal";
import { uploadLibraryImage } from "../../library/lib/upload-client";
import { cn } from "@/lib/utils";


interface ScheduleEntryRowProps {
  entry: ProjectScheduleEntryWithRelations;
  onRefresh: () => void;
  isSelected?: boolean;
  onSelect?: (e: React.MouseEvent) => void;
  openPicker: (entryId: string) => void;
  openEditor: (optionId: string, snapshot: ScheduleOptionSnapshot) => void;
}
export function ScheduleEntryRow({ 
  entry, 
  onRefresh,
  isSelected,
  onSelect,
  openPicker,
  openEditor
}: ScheduleEntryRowProps) {
  const [isDetailsOpen, setIsDetailsOpen] = React.useState(false);
  const [isUploading, setIsUploading] = React.useState(false);
  const [isPromoting, setIsPromoting] = React.useState(false);
  const [previewImage, setPreviewImage] = React.useState<string | undefined>(undefined);
  
  // Navigation State
  const [activeOptionId, setActiveOptionId] = React.useState<string | null>(
    entry.options.find(o => o.is_final)?.id || entry.options[0]?.id || null
  );

  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: entry.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    zIndex: isDragging ? 10 : 1,
  };

  // Derive active data
  const activeOption = entry.options.find(o => o.id === activeOptionId) || entry.options[0];
  const snapshot = activeOption?.data_snapshot as ScheduleOptionSnapshot | null | undefined;
  const hasMultipleOptions = entry.options.length > 1;

  const handleNextOption = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!activeOptionId) return;
    const currentIndex = entry.options.findIndex(o => o.id === activeOptionId);
    const nextIndex = (currentIndex + 1) % entry.options.length;
    setActiveOptionId(entry.options[nextIndex].id);
  };

  const handlePrevOption = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!activeOptionId) return;
    const currentIndex = entry.options.findIndex(o => o.id === activeOptionId);
    const prevIndex = (currentIndex - 1 + entry.options.length) % entry.options.length;
    setActiveOptionId(entry.options[prevIndex].id);
  };

  const handleDeleteEntry = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      unwrapActionResult(
        await deleteScheduleEntryAction({
          projectId: entry.project_id,
          entryId: entry.id,
        })
      );
      toast.success(`Deleted ${entry.schedule_code}`);
      onRefresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to delete entry");
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeOption) return;

    setIsUploading(true);
    try {
      const timestamp = Date.now();
      const safeFileName = file.name.replace(/[^a-z0-9.]/gi, "_").toLowerCase();
      const uploadPath = `schedule/${entry.id}_${timestamp}_${safeFileName}`;

      const imageUrl = await uploadLibraryImage(file, uploadPath);
      unwrapActionResult(
        await updateScheduleOptionSnapshotAction({
          optionId: activeOption.id,
          data: { catalog_image_url: imageUrl },
        })
      );
      toast.success("Image uploaded successfully");
      onRefresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Upload failed");
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const handlePromote = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!activeOption) return;
    
    setIsPromoting(true);
    try {
      unwrapActionResult(
        await promoteToLibraryAction({ optionId: activeOption.id })
      );
      toast.success("Request sent to Global Library");
      onRefresh();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to promote material");
    } finally {
      setIsPromoting(false);
    }
  };

  const getValidString = (val: unknown) => {
    if (!val) return null;
    const clean = String(val).trim().toUpperCase();
    // Reject empty strings, literal dashes, N/A, and dummy dimension placeholders
    const isInvalid = clean === '' || 
                      clean === '-' || 
                      clean === 'N/A' || 
                      clean === 'X X CM' ||
                      clean === 'XX CM';
                      
    return isInvalid ? null : String(val).trim();
  };

  const materialName = getValidString(snapshot?.catalog_product_name);
  const productSku = getValidString(snapshot?.specs?.catalog_sku);
  const isReservedValue = materialName === "[RESERVED]";

  // Substitution logic
  let displayTitle = "";
  if (!isReservedValue && (materialName || productSku)) {
    // Standard format: [SKU] - [Name] ex. [Brand]
    const brand = getValidString(snapshot?.catalog_brand);
    
    const parts = [];
    if (productSku) parts.push(productSku);
    if (materialName) parts.push(materialName);
    
    displayTitle = parts.join(" - ");
    if (brand) {
      displayTitle += ` ex. ${brand}`;
    }
  } else if (!isReservedValue) {
    // Fallback for empty Name and empty SKU -> Physical Identity
    const physicalParts = [
      getValidString(snapshot?.specs?.catalog_color), 
      getValidString(snapshot?.specs?.catalog_motif), 
      getValidString(snapshot?.specs?.catalog_finishing)
    ].filter(Boolean);
    
    displayTitle = physicalParts.length > 0 ? physicalParts.join(" — ") : "Action Required";
  } else {
    displayTitle = "[RESERVED]";
  }

  // Display Meta: Brand, Motif, Color, Finishing, Dimensions

  // Display Meta: Brand, Motif, Color, Finishing, Dimensions
  const displayMeta = [
    getValidString(snapshot?.catalog_sub_category), 
    getValidString(snapshot?.specs?.catalog_motif), 
    getValidString(snapshot?.catalog_initials_type) || getValidString(snapshot?.specs?.catalog_color), 
    getValidString(snapshot?.specs?.catalog_finishing),
    getValidString(snapshot?.specs?.catalog_dimensions)
  ]
  .filter(Boolean)
  // Deduplicate: If the value is already in the Title, don't show it in Meta
  .filter(val => !displayTitle.toLowerCase().includes(String(val).toLowerCase()))
  .join(' • ');





  const statusColor = {
    APPROVED: "bg-emerald-500",
    PENDING: "bg-amber-500",
    REJECTED: "bg-rose-500",
  };

  return (
    <TableRow
      ref={setNodeRef}
      style={style}
      onClick={onSelect}
      onDoubleClick={(e) => {
        e.stopPropagation();
        if (activeOption && snapshot) {
          openEditor(activeOption.id, snapshot);
        } else {
          openPicker(entry.id);
        }
      }}
      {...attributes}
      {...listeners}
      className={cn(
        "group/row border-b border-slate-100 transition-all duration-300 hover:bg-slate-50/50 cursor-pointer select-none h-32", // Increased to h-32 for better visibility
        isDragging ? "bg-white shadow-2xl scale-[1.01] z-50 cursor-grabbing" : "",
        isSelected ? "bg-blue-50/50 hover:bg-blue-50/80" : ""
      )}
    >

      {/* 1. CODE (w-20) */}
      <TableCell className="w-20 px-4 py-2 align-middle relative">
        <div className="flex items-center gap-2 group/code h-full">

          {hasMultipleOptions && (
            <div className="flex flex-col items-center gap-0.5 shrink-0" onClick={e => e.stopPropagation()}>
              <button 
                onClick={handlePrevOption}
                className="p-0.5 rounded hover:bg-slate-200 text-slate-400 hover:text-slate-900 transition-colors"
              >
                <ChevronUp className="h-3 w-3" />
              </button>
              <button 
                onClick={handleNextOption}
                className="p-0.5 rounded hover:bg-slate-200 text-slate-400 hover:text-slate-900 transition-colors"
              >
                <ChevronDown className="h-3 w-3" />
              </button>
            </div>
          )}
          
          <div className="flex-1 flex items-center justify-center relative gap-2">
            <div className="font-inter text-base font-black tracking-tighter text-slate-950 uppercase leading-none">{entry.schedule_code}</div>
            
            <div className="min-w-[18px] flex items-center justify-center">
              {activeOption?.material_catalog ? (
                <button 
                  onClick={handlePromote}
                  disabled={isPromoting || activeOption.material_catalog.status !== "REJECTED"}
                  className={cn(
                    "p-1 rounded-md text-white flex items-center justify-center shadow-sm border border-white/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed",
                    activeOption.material_catalog.status === "REJECTED" ? "cursor-pointer hover:scale-110" : "cursor-default",
                    statusColor[activeOption.material_catalog.status as keyof typeof statusColor] || "bg-slate-400"
                  )}
                  title={
                    activeOption.material_catalog.status === "REJECTED" 
                      ? "Rejected. Click to re-request approval." 
                      : `Global Library Status: ${activeOption.material_catalog.status}`
                  }
                >
                  {isPromoting ? (
                    <Loader2 className="h-2 w-2 animate-spin" />
                  ) : (
                    <Globe className="h-2 w-2 stroke-[3]" />
                  )}
                </button>
              ) : (
                <button
                  onClick={handlePromote}
                  disabled={isPromoting}
                  className="p-1 rounded-md bg-slate-100 text-slate-400 hover:text-slate-900 hover:bg-slate-200 flex items-center justify-center shadow-sm border border-slate-200 transition-transform hover:scale-110 opacity-0 group-hover/code:opacity-100"
                  title="Promote to Global Library"
                >
                  {isPromoting ? (
                    <Loader2 className="h-2 w-2 animate-spin" />
                  ) : (
                    <FileUp className="h-2 w-2 stroke-[3]" />
                  )}
                </button>
              )}
            </div>

          </div>
        </div>
      </TableCell>

      {/* 2. IMAGE (w-24) */}
      <TableCell className="w-24 px-4 py-2 align-middle text-center">

        <div className="relative inline-block group/image">
          {snapshot?.catalog_image_url ? (
            <button 
              onClick={(e) => {
                e.stopPropagation();
                setPreviewImage(snapshot.catalog_image_url || undefined);
              }}
              className="relative h-24 w-24 overflow-hidden rounded-md border border-slate-200 shadow-md transition-all hover:border-slate-900 group/btn bg-white"
            >
              <img
                src={snapshot.catalog_image_url}
                alt={displayTitle}
                className="h-full w-full object-cover transition-all duration-500 group-hover/btn:scale-110"
              />

            </button>
          ) : (
            <div 
              onClick={(e) => {
                e.stopPropagation();
                fileInputRef.current?.click();
              }}
              className="flex h-24 w-24 cursor-pointer items-center justify-center rounded-md border border-dashed border-slate-200 bg-slate-50/50 text-[10px] font-bold text-slate-300 hover:border-slate-300 hover:text-slate-400 transition-all group/empty"
            >
              <Plus className="h-6 w-6 group-hover/empty:scale-110 transition-transform" />
            </div>
          )}
          
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect} 
            onClick={(e) => e.stopPropagation()}
            accept="image/*" 
            className="hidden" 
          />
        </div>
        
        <ImageLightbox 
          src={previewImage || null} 
          onClose={() => setPreviewImage(undefined)} 
        />
      </TableCell>

      {/* 3. PRODUCT INFO (flex-1) */}
      <TableCell className="px-6 py-2 align-middle flex-1 min-w-[350px]">
        <div className="flex flex-col gap-1 truncate">
          <div className="flex items-center gap-2">
            <div className={cn(
              "font-lora font-semibold text-[15px] truncate leading-tight", // Premium serif heading
              isReservedValue ? "text-slate-300 italic" : "text-slate-900",
              isSelected ? "text-blue-900" : ""
            )}>
              {displayTitle}
            </div>
            {isReservedValue && (
              <div className="flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-50 border border-amber-100 flex-shrink-0">
                <div className="h-1 w-1 rounded-full bg-amber-500 animate-pulse" />
                <span className="text-[8px] font-black uppercase tracking-widest text-amber-600">Action Required</span>
              </div>
            )}
          </div>
          <div className="text-slate-400 text-[11px] font-medium uppercase tracking-wider truncate flex items-center gap-2">
            <span className="shrink-0 text-slate-900 px-1 py-0.5 bg-slate-100 rounded text-[9px] font-black">{snapshot?.schedule_category}</span>
            <span className="truncate">{displayMeta}</span>
          </div>
        </div>
      </TableCell>



      {/* 4. LOCATION (w-40) */}
      <TableCell className="w-40 px-6 py-2 align-middle">
        <div className="text-[12px] font-bold text-slate-800 truncate uppercase tracking-tight">
          {entry.schedule_location || "-"}
        </div>
      </TableCell>

      {/* 5. ACTIONS (w-16) */}
      <TableCell className="w-16 px-4 py-2 text-right align-middle">
        <div className="flex items-center justify-end opacity-0 group-hover/row:opacity-100 transition-opacity duration-200">
          <DropdownMenu>
            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
              <Button variant="ghost" className="h-8 w-8 p-0 text-slate-400 hover:text-slate-900 focus-visible:ring-0">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-[180px] rounded-xl">
              <DropdownMenuItem 
                className="cursor-pointer" 
                onClick={(e) => {
                  e.stopPropagation();
                  openPicker(entry.id);
                }}
              >
                <Plus className="mr-2 h-4 w-4" />
                Add Alternative
              </DropdownMenuItem>
              <DropdownMenuItem
                className="cursor-pointer text-rose-500 focus:text-rose-600"
                onClick={handleDeleteEntry}
              >
                <Trash2 className="mr-2 h-4 w-4" />
                Delete Entry
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </TableCell>

    </TableRow>
  );
}

"use client";

import * as React from "react";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { 
  Search, 
  Plus, 
  Loader2, 
  Package, 
  Check, 
  Building2,
  Calendar,
  Layers,
  Sparkles
} from "lucide-react";
import {
  getMaterialsAction,
  getVendorsAction,
} from "../../library/actions/library-actions";
import {
  addScheduleEntryAction,
  addScheduleOptionAction,
} from "@/actions/schedule-actions";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle 
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { CreatableSearch } from "@/components/ui/creatable-search";
import { cn } from "@/lib/utils";
import type {
  MaterialCatalogWithRelations,
  LibraryVendor,
} from "../../library/types";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import { ScheduleSection } from "@/generated/prisma";
import { useProjectScheduleContext } from "../context/ProjectScheduleContext";

type SchedulePickerPayload =
  | {
      projectId: string;
      category: string;
      section: ScheduleSection;
      mode: "catalog";
      catalogItemId: string;
    }
  | {
      projectId: string;
      category: string;
      section: ScheduleSection;
      mode: "create_catalog";
      catalogCreateData: {
        catalog_sku: string;
        catalog_brand: string;
        catalog_reference_url?: string | null;
      };
    }
  | {
      projectId: string;
      category: string;
      section: ScheduleSection;
      mode: "reserve";
    };

interface ScheduleMaterialPickerModalProps {
  entryId?: string; // If provided, we are adding an option to an existing entry
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
}

export function ScheduleMaterialPickerModal({
  entryId,
  isOpen,
  onOpenChange,
}: ScheduleMaterialPickerModalProps) {
  const { projectId, category, section, onSuccess } = useProjectScheduleContext();
  const [searchQuery, setSearchQuery] = React.useState("");
  const [materials, setMaterials] = React.useState<MaterialCatalogWithRelations[]>([]);
  const [vendors, setVendors] = React.useState<LibraryVendor[]>([]);
  const [isSearching, setIsSearching] = React.useState(false);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [selectedMaterialId, setSelectedMaterialId] = React.useState<string | null>(null);
  
  // Custom Creation State
  const [createCatalogName, setCreateCatalogName] = React.useState<string | null>(null);
  const [createBrand, setCreateBrand] = React.useState("");
  const [createReferenceUrl, setCreateReferenceUrl] = React.useState("");

  const fetchVendors = React.useCallback(async () => {
    try {
      const res = unwrapActionResult(await getVendorsAction(undefined));
      setVendors(res);
    } catch (e) {
      console.error("Failed to fetch vendors", e);
    }
  }, []);

  const fetchMaterials = React.useCallback(async () => {
    setIsSearching(true);
    try {
      const res = unwrapActionResult(await getMaterialsAction({ search: searchQuery }));
      setMaterials(res);
    } catch (error) {
      toast.error("Failed to fetch library catalog");
    } finally {
      setIsSearching(false);
    }
  }, [searchQuery]);

  React.useEffect(() => {
    if (isOpen) {
      fetchVendors();
      fetchMaterials();
    }
  }, [isOpen, fetchMaterials, fetchVendors]);

  // Load catalog options
  React.useEffect(() => {
    let isMounted = true;
    const run = async () => {
      setIsSearching(true);
      try {
        const results = unwrapActionResult(
          await getMaterialsAction({
            category: category !== "all" ? category : undefined,
            search: searchQuery.trim() || undefined,
          }),
        );
        if (isMounted) setMaterials(results);
      } catch (error) {
        console.error("Search failed:", error);
      } finally {
        if (isMounted) setIsSearching(false);
      }
    };

    const timer = setTimeout(() => { run(); }, 300);
    return () => {
      isMounted = false;
      clearTimeout(timer);
    };
  }, [category, searchQuery]);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      let payload: SchedulePickerPayload;

      if (createCatalogName) {
        payload = {
          projectId,
          category,
          section,
          mode: "create_catalog",
          catalogCreateData: {
            catalog_sku: createCatalogName, // Map name to SKU as fallback
            catalog_brand: createBrand.trim() || "Custom",
            catalog_reference_url: createReferenceUrl.trim() || null,
          },
        };
      } else {
        payload = {
          projectId,
          category,
          section,
          mode: "catalog",
          catalogItemId: selectedMaterialId as string,
        };
      }

      if (entryId) {
        unwrapActionResult(
          await addScheduleOptionAction({
            entryId: entryId,
            mode: payload.mode,
            ...(payload.mode === "catalog" ? { catalogItemId: payload.catalogItemId } : {}),
            ...(payload.mode === "create_catalog" ? { catalogCreateData: payload.catalogCreateData } : {}),
          }),
        );
        toast.success("New alternative option added successfully");
      } else {
        unwrapActionResult(await addScheduleEntryAction(payload));
        toast.success(`New row added to ${category}`);
      }

      onOpenChange(false);
      if (onSuccess) onSuccess();
      // Note: Removed router.refresh() - onSuccess already triggers fetchSchedule

      // Reset form
      setCreateBrand("");
      setCreateReferenceUrl("");
      setSelectedMaterialId(null);
      setCreateCatalogName(null);
    } catch (error: unknown) {
      toast.error(
        error instanceof Error ? error.message : "Something went wrong during submission"
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent 
        onKeyDown={(e) => e.stopPropagation()}
        className="sm:max-w-[1000px] p-0 overflow-hidden border-none rounded-[2rem] shadow-2xl bg-white focus-visible:outline-none"
      >
        <DialogHeader className="p-8 pb-6 border-b border-slate-100 bg-slate-50/30">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="h-12 w-12 rounded-2xl bg-slate-900 flex items-center justify-center text-white shadow-xl shadow-slate-200">
                <Layers className="h-6 w-6" />
              </div>
              <div>
                <DialogTitle className="font-lora text-2xl font-medium text-slate-900">
                  {entryId ? "Add Alternative Option" : "Add Row"}
                </DialogTitle>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Section:</span>
                  <Badge variant="outline" className="text-[10px] font-bold uppercase tracking-tighter border-slate-200 text-slate-500 rounded-sm px-1.5 h-4">
                    {section}
                  </Badge>
                  <span className="text-slate-300 mx-1">•</span>
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Category:</span>
                  <Badge className="bg-slate-900 text-white text-[10px] font-bold uppercase tracking-tighter rounded-sm px-1.5 h-4">
                    {category}
                  </Badge>
                </div>
              </div>
            </div>
            <div className="hidden md:flex flex-col items-end">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-300">Architecture Pillar 2</span>
              <span className="text-[9px] font-inter italic text-slate-400">Standardized Selection Protocol</span>
            </div>
          </div>
        </DialogHeader>

        <ScrollArea className="h-[430px] px-8 pb-8">
            <div className="space-y-4 pt-4">
              <div className="flex flex-col gap-2">
                <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Search Catalog or Define New</Label>
                <div className="relative group">
                  <CreatableSearch
                    options={materials.map((item) => ({
                      id: item.id,
                      name: `${item.catalog_sku} • ${item.vendor?.brand_name ?? "Unknown Brand"}`,
                      badge: item.status === 'APPROVED' ? "Gold" : "Queue"
                    }))}
                    value={selectedMaterialId ?? undefined}
                    onSelect={(id: string) => {
                      setSelectedMaterialId(id);
                      setCreateCatalogName(null);
                    }}
                    onCreate={(name: string) => {
                      setCreateCatalogName(name);
                      setSelectedMaterialId(null);
                      setSearchQuery(name);
                    }}
                    onSearchChange={setSearchQuery}
                    placeholder="Type brand, material name, or motif..."
                    allowFreeText
                  />
                </div>
              </div>

            {isSearching ? (
              <div className="flex flex-col items-center justify-center py-20 gap-4 opacity-50">
                <Loader2 className="h-10 w-10 animate-spin text-slate-900" />
                <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 animate-pulse">
                  Scanning Archives...
                </p>
              </div>
            ) : materials.length > 0 ? (
              <div className="border border-slate-100 rounded-2xl overflow-hidden bg-white shadow-sm ring-1 ring-slate-100/50">
                <Table>
                  <TableHeader className="bg-slate-50/50">
                    <TableRow className="hover:bg-transparent border-slate-100">
                      <TableHead className="w-16 h-12"></TableHead>
                      <TableHead className="h-12 text-[10px] font-black uppercase tracking-widest text-slate-400">
                        Material Details
                      </TableHead>
                      <TableHead className="h-12 text-[10px] font-black uppercase tracking-widest text-slate-400">
                        Brand / Origin
                      </TableHead>
                      <TableHead className="w-10 h-12"></TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {materials.map((item) => (
                      <TableRow
                        key={item.id}
                        onClick={() => setSelectedMaterialId(item.id)}
                        className={cn(
                          "cursor-pointer transition-colors group h-16 border-slate-50",
                          selectedMaterialId === item.id
                            ? "bg-slate-900/5 hover:bg-slate-900/10"
                            : "hover:bg-slate-50",
                        )}
                      >
                        <TableCell className="py-2">
                          <div className="h-12 w-12 rounded-lg bg-slate-50 border border-slate-100 overflow-hidden flex items-center justify-center shrink-0">
                            {item.catalog_image_url ? (
                              <img
                                src={item.catalog_image_url}
                                alt={item.catalog_sku}
                                className="w-full h-full object-cover"
                              />
                            ) : (
                              <Package className="h-5 w-5 text-slate-200" />
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="py-2">
                          <div className="flex flex-col gap-0.5">
                            <div className="flex items-center gap-2">
                              <span className="text-sm font-semibold text-slate-900">
                                {item.catalog_sku}
                              </span>
                              {item.status === "APPROVED" ? (
                                <Badge className="bg-emerald-50 text-emerald-600 border-emerald-100 text-[8px] font-black uppercase h-4 px-1.5 shadow-none">
                                  Gold
                                </Badge>
                              ) : (
                                <Badge className="bg-amber-50 text-amber-600 border-amber-100 text-[8px] font-black uppercase h-4 px-1.5 shadow-none">
                                  In Review
                                </Badge>
                              )}
                            </div>
                            {item.catalog_sub_category && (
                              <span className="text-[10px] text-slate-400 font-medium uppercase tracking-tight">
                                {item.catalog_sub_category}
                              </span>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="py-2">
                          <div className="flex items-center gap-2">
                            <Building2 className="h-3 w-3 text-slate-300" />
                            <span className="text-xs font-medium text-slate-600">
                              {item.vendor?.brand_name || "Bespoke / Custom"}
                            </span>
                          </div>
                        </TableCell>
                        <TableCell className="py-2 pr-6">
                          {selectedMaterialId === item.id ? (
                            <div className="h-6 w-6 rounded-full bg-slate-900 flex items-center justify-center text-white scale-100 animate-in zoom-in-50 duration-300">
                              <Check className="h-3.5 w-3.5 stroke-[3]" />
                            </div>
                          ) : (
                            <div className="h-6 w-6 rounded-full border border-slate-200 group-hover:border-slate-300 transition-colors" />
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            ) : searchQuery ? (
              <div className="py-20 text-center">
                <p className="text-sm font-inter text-slate-400 italic">
                  No matches found for &quot;{searchQuery}&quot;
                </p>
              </div>
            ) : (
              <div className="py-20 text-center space-y-2 opacity-30 italic font-inter font-medium text-slate-400 text-sm">
                Type to explore the global material library...
              </div>
            )}

            {createCatalogName && (
              <div className="rounded-2xl border-2 border-slate-900 bg-white p-6 space-y-5 shadow-xl animate-in fade-in zoom-in-95 duration-300">
                <div className="flex items-center gap-3">
                   <div className="h-8 w-8 rounded-lg bg-slate-900 flex items-center justify-center text-white">
                      <Plus className="h-4 w-4" />
                   </div>
                   <div>
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">New Catalog Intent</p>
                      <p className="text-sm font-semibold text-slate-900 underline decoration-slate-200 underline-offset-4">{createCatalogName}</p>
                   </div>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Vendor / Brand</Label>
                    <Input
                      value={createBrand}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCreateBrand(e.target.value)}
                      placeholder="e.g. Roman, KIA, or Custom"
                      className="h-11 bg-slate-50 border-none rounded-xl font-inter text-sm"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">External Reference Link</Label>
                    <Input
                      value={createReferenceUrl}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCreateReferenceUrl(e.target.value)}
                      placeholder="https://www.tokopedia.com/..."
                      className="h-11 bg-slate-50 border-none rounded-xl font-inter text-sm"
                    />
                  </div>
                </div>
                <p className="text-[10px] font-medium text-slate-400 italic">
                  * Creating this will automatically harvest the data into Global Library (Pending Review)
                </p>
              </div>
            )}
          </div>
        </ScrollArea>

        <div className="p-8 pt-4 border-t border-slate-100 bg-slate-50/50 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="text-[10px] font-bold font-inter text-slate-400 uppercase tracking-widest">
            {selectedMaterialId ? "1 Item Selected" : createCatalogName ? "New Item Ready" : "Selection Required"}
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <Button
              variant="ghost"
              onClick={async () => {
                setIsSubmitting(true);
                try {
                  const payload: SchedulePickerPayload = { projectId, category, section, mode: "reserve" };
                  if (entryId) {
                    unwrapActionResult(await addScheduleOptionAction({ entryId, mode: "reserve" }));
                    toast.success("Reserved placeholder option added");
                  } else {
                    unwrapActionResult(await addScheduleEntryAction(payload));
                    toast.success("Code reserved successfully");
                  }
                  onOpenChange(false);
                  if (onSuccess) onSuccess();
                  // Note: Removed router.refresh() - onSuccess already triggers fetchSchedule
                } catch (e: unknown) {
                  toast.error(e instanceof Error ? e.message : "Failed to reserve code");
                } finally {
                  setIsSubmitting(false);
                }
              }}
              disabled={isSubmitting}
              className="flex-1 md:flex-initial h-12 px-6 rounded-2xl font-inter font-bold text-xs uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-all border border-slate-200"
            >
              Reserve Code
            </Button>

            <Button
              variant="ghost"
              onClick={() => onOpenChange(false)}
              className="flex-1 md:flex-initial h-12 px-6 rounded-2xl font-inter font-bold text-xs uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-all"
            >
              Cancel
            </Button>

            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || (!selectedMaterialId && !createCatalogName)}
              className="flex-1 md:flex-initial bg-slate-950 hover:bg-slate-800 text-white rounded-2xl h-12 px-10 shadow-xl shadow-slate-200 transition-all font-inter font-bold text-xs uppercase tracking-widest relative overflow-hidden"
            >
              {isSubmitting ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <>
                  {entryId ? "Add Option" : "Add Row"}
                  <Plus className="ml-2 h-3.5 w-3.5" />
                </>
              )}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { CheckCircle2, Package, Clock, XCircle, Plus, Sparkles } from "lucide-react";
import { ProjectScheduleOptionWithMaterial, ScheduleOptionSnapshot } from "../types";
import { approveScheduleOptionAction } from "@/actions/schedule-actions";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import { ImageLightbox } from "@/components/ui/image-lightbox";

interface ScheduleOptionCardProps {
  option: ProjectScheduleOptionWithMaterial;
  entryId: string;
  onRefresh: () => void;
}

export function ScheduleOptionCard({ option, entryId, onRefresh }: ScheduleOptionCardProps) {
  const [previewImage, setPreviewImage] = React.useState<string | undefined>(undefined);
  const snapshot = option.data_snapshot as ScheduleOptionSnapshot | null | undefined;

  const handleApprove = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (option.is_final) return;

    try {
      unwrapActionResult(await approveScheduleOptionAction({ 
        optionId: option.id,
        entryId,
      }));
      toast.success(`Option ${option.option_label} has been approved`);
      onRefresh();
    } catch {
      toast.error("Failed to approve option");
    }
  };

  const getStatusStyle = () => {
    if (option.is_final) return "border-slate-950 ring-4 ring-slate-950/5 bg-white scale-[1.05] z-10 shadow-2xl";
    if (option.status === "NOT_USED") return "opacity-40 grayscale border-slate-100 bg-slate-50/50";
    if (option.status === "DRAFT") return "border-dashed border-slate-200 bg-slate-50/10";
    return "border-slate-100 bg-white hover:border-slate-400 shadow-sm";
  };

  return (
    <div 
      onClick={handleApprove}
      className={`relative w-24 h-24 rounded-2xl border-2 transition-all cursor-pointer group/opt overflow-hidden ${getStatusStyle()}`}
    >
      {/* Label Badge */}
      <div className={`absolute top-2 left-2 z-20 h-7 w-7 rounded-lg flex items-center justify-center font-lora text-xs font-black shadow-lg transition-all duration-500 ${option.is_final ? "bg-slate-950 text-white scale-110" : "bg-white/90 backdrop-blur-md text-slate-400 group-hover/opt:text-slate-950 group-hover/opt:scale-110 border border-slate-100"}`}>
        {option.option_label}
      </div>

      {option.material_catalog_id && (
        <div 
          className="absolute top-2 right-6 z-20 h-4 w-4 rounded-full bg-slate-900 border-2 border-white flex items-center justify-center shadow-lg transform transition-transform group-hover/opt:scale-110"
          title="Gold Standard Library Item"
        >
          <Sparkles className="h-2 w-2 text-white" />
        </div>
      )}

      {/* Sample Ready Indicator (Loose Coupling Bridge) */}
      {option.material_catalog?.material_requests?.some(r => r.status === 'RECEIVED') && (
        <div 
          className="absolute top-7 right-2 z-20 flex items-center gap-1 bg-emerald-500 text-white text-[7px] font-black px-1 py-0.5 rounded-full shadow-lg border-2 border-white animate-in zoom-in duration-500"
          title="Physical Sample Ready"
        >
          <CheckCircle2 className="h-2 w-2" />
          <span className="pr-0.5">READY</span>
        </div>
      )}

      {/* Content */}
      <div className="w-full h-full flex flex-col items-center justify-center">
        {snapshot?.catalog_image_url ? (
          <div className="relative w-full h-full group/img">
            <img 
              src={snapshot.catalog_image_url} 
              alt={option.option_label} 
              className="w-full h-full object-cover transition-transform group-hover/opt:scale-110"
            />
            <button
              onClick={(e) => {
                e.stopPropagation();
                setPreviewImage(snapshot.catalog_image_url || undefined);
              }}
              className="absolute inset-0 bg-black/0 group-hover/img:bg-black/20 flex items-center justify-center transition-colors opacity-0 group-hover/img:opacity-100"
            >
               <div className="bg-white/90 backdrop-blur p-1.5 rounded-full shadow-lg transform scale-75 group-hover/img:scale-100 transition-transform">
                  <Plus className="h-3 w-3 text-slate-900" />
               </div>
            </button>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-1.5 transition-colors group-hover/opt:text-slate-900 text-slate-300 p-2 pt-4">
             <Package className="h-6 w-6" />
             <span className="text-[8px] font-black uppercase tracking-widest leading-none">
               {option.status}
             </span>
          </div>
        )}
      </div>

      {/* Status Indicators */}
      {option.is_final ? (
        <div className="absolute top-1 right-1 z-20">
           <CheckCircle2 className="h-4 w-4 text-slate-900 bg-white rounded-full shadow-sm" />
        </div>
      ) : option.status === "DRAFT" ? (
        <div className="absolute top-1 right-1 z-20">
           <Clock className="h-3.5 w-3.5 text-slate-300 bg-white rounded-full" />
        </div>
      ) : option.status === "NOT_USED" ? (
        <div className="absolute top-1 right-1 z-20">
           <XCircle className="h-3.5 w-3.5 text-rose-300 bg-white rounded-full" />
        </div>
      ) : null}
      
      <div className="absolute bottom-0 left-0 right-0 p-1 bg-gradient-to-t from-white/95 to-transparent flex justify-center opacity-0 group-hover/opt:opacity-100 transition-opacity">
<span className="text-[7px] font-black uppercase text-slate-500 line-clamp-1 truncate w-full text-center px-1">
            {snapshot?.catalog_product_name || snapshot?.specs?.catalog_motif || "Empty Varian"}
          </span>
      </div>

      <ImageLightbox 
        src={previewImage || null} 
        onClose={() => setPreviewImage(undefined)} 
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { Search, Plus, Loader2, X, ChevronRight } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { toast } from "sonner";
import { unwrapActionResult } from "@/lib/result";
import { ScheduleSection } from "@/generated/prisma";
import { getMaterialsAction } from "@/extensions/library/actions/library-actions";
import { 
  addScheduleEntryWithMaterialAction, 
  addScheduleEntryInstantAction,
  updateScheduleOptionSnapshotAction,
  getScheduleCategoriesAction 
} from "@/actions/schedule-actions";
import { cn } from "@/lib/utils";
import type { MaterialCatalogWithRelations } from "@/extensions/library/types";

interface ScheduleSearchBarProps {
  projectId: string;
  section: ScheduleSection;
  onSuccess: () => void;
}

export function ScheduleSearchBar({ projectId, section, onSuccess }: ScheduleSearchBarProps) {
  const [query, setQuery] = React.useState("");
  const [isSearching, setIsSearching] = React.useState(false);
  const [isCreating, setIsCreating] = React.useState(false);
  const [materials, setMaterials] = React.useState<MaterialCatalogWithRelations[]>([]);
  const [showResults, setShowResults] = React.useState(false);
  
  // Creation Flow State
  const [step, setStep] = React.useState<"SEARCH" | "CATEGORY">("SEARCH");
  const [newMaterialName, setNewMaterialName] = React.useState("");
  const [categories, setCategories] = React.useState<string[]>([]);
  const [categoryQuery, setCategoryQuery] = React.useState("");

  const searchRef = React.useRef<HTMLDivElement>(null);

  // Close results on click outside
  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowResults(false);
        if (step === "CATEGORY") reset();
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [step]);

  const loadMaterials = React.useCallback(async (q: string) => {
    if (!q.trim()) {
      setMaterials([]);
      return;
    }
    setIsSearching(true);
    try {
      const results = unwrapActionResult(await getMaterialsAction({ 
        search: q,
        limit: 10 
      })) as MaterialCatalogWithRelations[];
      setMaterials(results);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSearching(false);
    }
  }, []);

  const loadCategories = async () => {
    try {
      const results = unwrapActionResult(await getScheduleCategoriesAction({ section })) as { category: string }[];
      setCategories(results.map(r => r.category));
    } catch (error) {
      console.error("Failed to load categories:", error);
    }
  };

  React.useEffect(() => {
    const timeout = setTimeout(() => {
      if (query && step === "SEARCH") loadMaterials(query);
    }, 300);
    return () => clearTimeout(timeout);
  }, [query, loadMaterials, step]);

  const reset = () => {
    setQuery("");
    setMaterials([]);
    setShowResults(false);
    setStep("SEARCH");
    setNewMaterialName("");
    setCategoryQuery("");
  };

  const handleSelectMaterial = async (material: MaterialCatalogWithRelations) => {
    setIsCreating(true);
    try {
      await addScheduleEntryWithMaterialAction({
        projectId,
        materialId: material.id,
        section,
      });
      toast.success(`Added: ${material.catalog_product_name}`);
      reset();
      onSuccess();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to add material");
    } finally {
      setIsCreating(false);
    }
  };

  const handleStartCreateNew = () => {
    setNewMaterialName(query);
    setStep("CATEGORY");
    loadCategories();
    setCategoryQuery("");
  };

  const handleFinalizeCreate = async (category: string) => {
    setIsCreating(true);
    try {
const entry = unwrapActionResult(await addScheduleEntryInstantAction({
          projectId,
          schedule_category: category.toUpperCase(),
          section,
        }));

        if (entry?.options?.[0]) {
          await updateScheduleOptionSnapshotAction({
            optionId: entry.options[0].id,
            data: { catalog_product_name: newMaterialName }
          });
      }

      toast.success(`Created: ${newMaterialName}`);
      reset();
      onSuccess();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to create entry");
    } finally {
      setIsCreating(false);
    }
  };

  const filteredCategories = categories.filter(c => 
    c.toLowerCase().includes(categoryQuery.toLowerCase())
  );

  return (
    <div ref={searchRef} className="relative w-full max-w-2xl">
      <div className={cn(
        "flex items-center gap-3 px-4 h-12 rounded-xl border transition-all duration-200",
        showResults ? "bg-white border-slate-900 shadow-lg ring-4 ring-slate-100" : "bg-slate-50 border-slate-200 hover:border-slate-300"
      )}>
        <Search className={cn("h-4 w-4 shrink-0 transition-colors", showResults ? "text-slate-900" : "text-slate-400")} />
        
        {step === "SEARCH" ? (
          <input
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setShowResults(true);
            }}
            onFocus={() => setShowResults(true)}
            placeholder="Search material libraries or type new name to add..."
            className="flex-1 bg-transparent border-none outline-none text-sm font-medium text-slate-900 placeholder:text-slate-400"
          />
        ) : (
          <div className="flex-1 flex items-center gap-2 overflow-hidden">
            <span className="shrink-0 px-2 py-0.5 rounded-md bg-slate-900 text-white text-[10px] font-bold uppercase tracking-wider">
              NEW: {newMaterialName}
            </span>
            <ChevronRight className="h-3 w-3 text-slate-300 shrink-0" />
            <input
              autoFocus
              value={categoryQuery}
              onChange={(e) => setCategoryQuery(e.target.value)}
              placeholder="Type or select category..."
              className="flex-1 bg-transparent border-none outline-none text-sm font-medium text-slate-900 placeholder:text-slate-400"
            />
          </div>
        )}

        {(query || categoryQuery) && (
          <button 
            onClick={reset}
            className="p-1 rounded-full hover:bg-slate-100 transition-colors"
          >
            <X className="h-3.5 w-3.5 text-slate-400" />
          </button>
        )}

        {isCreating && <Loader2 className="h-4 w-4 animate-spin text-slate-400" />}
      </div>

      {/* Results Dropdown */}
      {showResults && (
        <div className="absolute top-full left-0 right-0 mt-2 z-50 bg-white rounded-2xl border border-slate-200 shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <ScrollArea className="max-h-[400px]">
            <div className="p-2 space-y-1">
              {step === "SEARCH" ? (
                <>
                  {materials.length > 0 ? (
                    <>
                      <div className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        From Library
                      </div>
                      {materials.map((m) => (
                        <button
                          key={m.id}
                          onClick={() => handleSelectMaterial(m)}
                          className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-left hover:bg-slate-50 transition-colors group"
                        >
                          <div className="h-10 w-10 rounded-lg bg-slate-100 overflow-hidden shrink-0 border border-slate-100">
                            {m.catalog_image_url ? (
                              <img src={m.catalog_image_url} alt="" className="h-full w-full object-cover" />
                            ) : (
                              <div className="h-full w-full bg-slate-50 flex items-center justify-center text-[10px] text-slate-300 uppercase font-black">NA</div>
                            )}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="text-sm font-semibold text-slate-900 truncate group-hover:text-slate-950">
                              {m.catalog_product_name}
                            </div>
                            <div className="text-[11px] text-slate-500 truncate">
                              {m.catalog_brand || m.vendor?.brand_name || "Unknown Brand"} • {m.catalog_category}
                            </div>
                          </div>
                        </button>
                      ))}
                    </>
                  ) : query.length >= 2 && !isSearching ? (
                    <div className="px-3 py-8 text-center text-slate-400 text-xs italic">
                      No matching materials found in library.
                    </div>
                  ) : null}

                  {query.trim().length > 0 && (
                    <button
                      onClick={handleStartCreateNew}
                      className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left hover:bg-slate-900 hover:text-white transition-all group"
                    >
                      <div className="h-10 w-10 rounded-lg bg-emerald-50 text-emerald-600 flex items-center justify-center group-hover:bg-emerald-500 group-hover:text-white transition-colors">
                        <Plus className="h-5 w-5" />
                      </div>
                      <div className="flex-1">
                        <div className="text-sm font-bold">Create custom entry</div>
                        <div className="text-[11px] opacity-70 italic">&quot;{query}&quot; (not in library)</div>
                      </div>
                    </button>
                  )}
                </>
              ) : (
                <>
                  <div className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Select Category for &quot;{newMaterialName}&quot;
                  </div>
                  {filteredCategories.map((cat) => (
                    <button
                      key={cat}
                      onClick={() => handleFinalizeCreate(cat)}
                      className="flex w-full items-center justify-between rounded-xl px-3 py-3 text-left hover:bg-slate-50 transition-colors group"
                    >
                      <span className="text-sm font-medium text-slate-900 uppercase tracking-tight">{cat}</span>
                      <Plus className="h-4 w-4 text-slate-300 group-hover:text-slate-900" />
                    </button>
                  ))}
                  {categoryQuery && !categories.some(c => c.toLowerCase() === categoryQuery.toLowerCase()) && (
                    <button
                      onClick={() => handleFinalizeCreate(categoryQuery)}
                      className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors"
                    >
                      <Plus className="h-4 w-4" />
                      <div className="text-sm font-bold">Create Category: &quot;{categoryQuery.toUpperCase()}&quot;</div>
                    </button>
                  )}
                </>
              )}
            </div>
          </ScrollArea>
        </div>
      )}
    </div>
  );
}

